/**
  **************************************************************************
  * @file     iap.c
  * @brief    IAP 升级协议、定长帧解析、Trailer 验签及状态机驱动实现
  **************************************************************************
  */

#include "iap.h"

static iap_state_t s_iap_state = IAP_STATE_IDLE;
static uint32_t s_target_fw_len = 0U;
static uint8_t s_chunk0_buf[CHUNK_MAX_SIZE];
static bool s_has_cached_chunk0 = false;
static fw_trailer_t s_cached_trailer;

/**
  * @brief  查询当前是否已进入升级中状态
  */
bool iap_is_upgrade_active(void)
{
  return (s_iap_state != IAP_STATE_IDLE);
}

/**
  * @brief  计算 8 位累加和校验值 Checksum = (CMD + Len_L + Len_H + sum(Payload)) & 0xFF
  */
uint8_t iap_checksum_calc(uint8_t cmd, uint16_t len, const uint8_t *p_payload)
{
  uint32_t sum = (uint32_t)cmd + (uint32_t)(len & 0xFFU) + (uint32_t)((len >> 8U) & 0xFFU);
  if (p_payload != NULL)
  {
    for (uint16_t i = 0U; i < len; i++)
    {
      sum += (uint32_t)p_payload[i];
    }
  }
  return (uint8_t)(sum & 0xFFU);
}

/**
  * @brief  纯软件增量计算 CRC32 (IEEE 802.3 标准)
  */
static uint32_t iap_crc32_accumulate(uint32_t crc, const uint8_t *p_data, uint32_t len)
{
  if (p_data == NULL || len == 0U)
  {
    return crc;
  }

  for (uint32_t i = 0U; i < len; i++)
  {
    crc ^= (uint32_t)p_data[i];
    for (uint8_t bit = 0U; bit < 8U; bit++)
    {
      if ((crc & 1U) != 0U)
      {
        crc = (crc >> 1U) ^ 0xEDB88320U;
      }
      else
      {
        crc = (crc >> 1U);
      }
    }
  }
  return crc;
}

/**
  * @brief  纯软件计算单段 CRC32 (IEEE 802.3 标准)
  */
uint32_t iap_crc32_calc(const uint8_t *p_data, uint32_t len)
{
  return ~iap_crc32_accumulate(0xFFFFFFFFU, p_data, len);
}

/**
  * @brief  校验 128 字节 Trailer 元数据合法性
  */
bool iap_trailer_validate(const fw_trailer_t *p_trailer)
{
  if (p_trailer == NULL)
  {
    return false;
  }

  bool is_magic_ok = (p_trailer->magic == TRAILER_MAGIC);
  bool is_board_ok = (p_trailer->board_id == BOARD_ID_TH);
  bool is_len_ok = (p_trailer->payload_len > 0U) && (p_trailer->payload_len <= APP_MAX_SIZE);

  if (!is_magic_ok || !is_board_ok || !is_len_ok)
  {
    LOG_ERR("Trailer check failed: magic/board/len invalid");
    return false;
  }

  uint32_t calc_crc = iap_crc32_calc((const uint8_t *)p_trailer, 124U);
  if (calc_crc != p_trailer->trailer_crc32)
  {
    LOG_ERR("Trailer CRC32 mismatch: exp=0x%08X, got=0x%08X",
            (unsigned int)p_trailer->trailer_crc32, (unsigned int)calc_crc);
    return false;
  }

  return true;
}

/**
  * @brief  发送私有定长协议帧
  *         格式: [5A A5] + [CMD: 1B] + [Length: 2B (小端)] + [Payload: N B] + [Checksum: 1B]
  */
static void iap_send_frame(uint8_t cmd, const uint8_t *p_payload, uint16_t len)
{
  uint8_t tx_buf[FRAME_MAX_PAYLOAD + 6U];
  tx_buf[0] = FRAME_SOF1;
  tx_buf[1] = FRAME_SOF2;
  tx_buf[2] = cmd;
  tx_buf[3] = (uint8_t)(len & 0xFFU);
  tx_buf[4] = (uint8_t)((len >> 8U) & 0xFFU);

  for (uint16_t i = 0U; i < len; i++)
  {
    tx_buf[5U + i] = p_payload[i];
  }

  uint8_t checksum = iap_checksum_calc(cmd, len, p_payload);
  tx_buf[5U + len] = checksum;

  bsp_uart1_send_data(tx_buf, 6U + len);
}

/**
  * @brief  发送 CMD_TH_HELLO 握手报到帧
  *         Payload 结构: AppValid(1B) + BoardID(4B) + Version(4B)
  */
void iap_send_hello(void)
{
  uint8_t payload[9];
  uint32_t board_id = BOARD_ID_TH;
  uint32_t bl_ver = BL_VERSION_CODE;
  uint8_t app_valid = bsp_flash_app_integrity_check() ? 1U : 0U;

  payload[0] = app_valid;
  payload[1] = (uint8_t)(board_id & 0xFFU);
  payload[2] = (uint8_t)((board_id >> 8U) & 0xFFU);
  payload[3] = (uint8_t)((board_id >> 16U) & 0xFFU);
  payload[4] = (uint8_t)((board_id >> 24U) & 0xFFU);

  payload[5] = (uint8_t)(bl_ver & 0xFFU);
  payload[6] = (uint8_t)((bl_ver >> 8U) & 0xFFU);
  payload[7] = (uint8_t)((bl_ver >> 16U) & 0xFFU);
  payload[8] = (uint8_t)((bl_ver >> 24U) & 0xFFU);

  LOG_INFO("Sending CMD_TH_HELLO (AppValid=%d)", app_valid);
  iap_send_frame(CMD_TH_HELLO, payload, 9U);
}

/**
  * @brief  处理 CMD_TH_START_UPG 升级开始指令
  */
static void iap_handle_start_upg(const uint8_t *p_payload, uint16_t len)
{
  uint8_t ack_status = IAP_STATUS_OK;
  s_has_cached_chunk0 = false;
  if (len < sizeof(fw_trailer_t))
  {
    ack_status = IAP_START_STATUS_SIZE_ERR;
    iap_send_frame(ACK_TH_START_UPG, &ack_status, 1U);
    return;
  }

  const fw_trailer_t *p_trailer = (const fw_trailer_t *)p_payload;
  if (p_trailer->magic != TRAILER_MAGIC) { ack_status = IAP_START_STATUS_MAGIC_ERR; }
  else if (p_trailer->board_id != BOARD_ID_TH) { ack_status = IAP_START_STATUS_BOARD_ERR; }
  else if ((p_trailer->payload_len == 0U) || (p_trailer->payload_len > APP_MAX_SIZE))
  {
    ack_status = IAP_START_STATUS_SIZE_ERR;
  }
  else if (!iap_trailer_validate(p_trailer)) { ack_status = IAP_START_STATUS_TRAILER_CRC_ERR; }
  else
  {
    s_cached_trailer = *p_trailer;
    s_target_fw_len = p_trailer->payload_len;
    LOG_INFO("Trailer verified. TargetLen=%u. Erasing app & anchor sectors...", (unsigned int)s_target_fw_len);
    flash_result_t erase_res = bsp_flash_erase_first_app_sector();
    flash_result_t anchor_res = bsp_flash_erase_anchor_sector();
    if (erase_res != FLASH_STATUS_OK || anchor_res != FLASH_STATUS_OK)
    {
      ack_status = IAP_START_STATUS_ERASE_ERR;
      LOG_ERR("Erase sector failed: res=%d anchor=%d", erase_res, anchor_res);
    }
    else
    {
      s_iap_state = IAP_STATE_RECEIVING_CHUNKS;
      LOG_INFO("App & anchor sectors erased. TH ready for chunks.");
    }
  }

  iap_send_frame(ACK_TH_START_UPG, &ack_status, 1U);
}

/**
  * @brief  处理 CMD_TH_PUSH_CHUNK 分块写入指令 (ChunkIndex + 512B 数据)
  */
/**
  * @brief  跨扇区边界写入单个数据块并执行物理回读比对
  */
static flash_result_t iap_write_chunk_to_flash(uint32_t offset, const uint8_t *p_data)
{
  uint32_t write_addr = APP_START_ADDR + offset;
  if (((offset % FLASH_SECTOR_SIZE) == 0U) && (offset > 0U))

  {
    bsp_flash_erase_sector(write_addr);
  }
  return bsp_flash_write_and_verify(write_addr, p_data, CHUNK_MAX_SIZE);
}

/**
  * @brief  处理 CMD_TH_PUSH_CHUNK 分块写入指令 (ChunkIndex + 512B 数据)
  */
static void iap_handle_push_chunk(const uint8_t *p_payload, uint16_t len)
{
  uint8_t ack_payload[5] = {0U, 0U, 0U, 0U, IAP_CHUNK_STATUS_ERR};
  if (s_iap_state != IAP_STATE_RECEIVING_CHUNKS || len != 516U)
  {
    iap_send_frame(ACK_TH_PUSH_CHUNK, ack_payload, 5U);
    return;
  }

  uint32_t chunk_idx = (uint32_t)p_payload[0] | ((uint32_t)p_payload[1] << 8U) |
                       ((uint32_t)p_payload[2] << 16U) | ((uint32_t)p_payload[3] << 24U);
  for (uint8_t k = 0U; k < 4U; k++) { ack_payload[k] = p_payload[k]; }
  ack_payload[4] = IAP_CHUNK_STATUS_OK;

  if (chunk_idx == 0U)
  {
    for (uint16_t i = 0U; i < CHUNK_MAX_SIZE; i++) { s_chunk0_buf[i] = p_payload[4U + i]; }
    s_has_cached_chunk0 = true;
    iap_send_frame(ACK_TH_PUSH_CHUNK, ack_payload, 5U);
    return;
  }

  uint32_t offset = chunk_idx * CHUNK_MAX_SIZE;
  if (offset + CHUNK_MAX_SIZE > APP_MAX_SIZE)
  {
    ack_payload[4] = IAP_CHUNK_STATUS_ERR;
    iap_send_frame(ACK_TH_PUSH_CHUNK, ack_payload, 5U);
    return;
  }

  flash_result_t write_res = iap_write_chunk_to_flash(offset, &p_payload[4]);
  if (write_res != FLASH_STATUS_OK)
  {
    ack_payload[4] = IAP_CHUNK_STATUS_ERR;
    LOG_ERR("Write/Verify chunk fail at idx %u, res=%d", (unsigned int)chunk_idx, write_res);
  }
  iap_send_frame(ACK_TH_PUSH_CHUNK, ack_payload, 5U);
}

/**
  * @brief  计算当前已接收完整固件的 CRC32 (联合 SRAM Chunk 0 与 Flash 后续)
  */
static uint32_t iap_calculate_firmware_crc32(void)
{
  if (!s_has_cached_chunk0)
  {
    return iap_crc32_calc((const uint8_t *)APP_START_ADDR, s_target_fw_len);
  }

  uint32_t c0_len = (s_target_fw_len < CHUNK_MAX_SIZE) ? s_target_fw_len : CHUNK_MAX_SIZE;
  uint32_t crc_accum = iap_crc32_accumulate(0xFFFFFFFFU, s_chunk0_buf, c0_len);
  if (s_target_fw_len > CHUNK_MAX_SIZE)
  {
    const uint8_t *p_flash_tail = (const uint8_t *)(APP_START_ADDR + CHUNK_MAX_SIZE);
    crc_accum = iap_crc32_accumulate(crc_accum, p_flash_tail, s_target_fw_len - CHUNK_MAX_SIZE);
  }
  return ~crc_accum;
}

/**
  * @brief  将固件元数据锚点固化写入 Sector 127
  */
static flash_result_t iap_commit_anchor_metadata(uint32_t fw_crc)
{
  app_anchor_meta_t anchor;
  anchor.anchor_magic = ANCHOR_MAGIC;
  anchor.trailer = s_cached_trailer;
  anchor.firmware_crc32 = fw_crc;
  anchor.anchor_crc32 = iap_crc32_calc((const uint8_t *)&anchor, 136U);
  return bsp_flash_write_and_verify(TRAILER_ANCHOR_ADDR, (const uint8_t *)&anchor, sizeof(app_anchor_meta_t));
}

/**
  * @brief  处理 CMD_TH_FINISH 传输完成与终验指令
  */
static void iap_handle_finish(const uint8_t *p_payload, uint16_t len)
{
  uint8_t ack_status = IAP_FINISH_STATUS_OK;
  if (len < 4U)
  {
    ack_status = IAP_FINISH_STATUS_CRC_ERR;
    iap_send_frame(ACK_TH_FINISH, &ack_status, 1U);
    return;
  }

  uint32_t exp_crc32 = (uint32_t)p_payload[0] | ((uint32_t)p_payload[1] << 8U) |
                       ((uint32_t)p_payload[2] << 16U) | ((uint32_t)p_payload[3] << 24U);
  uint32_t calc_crc32 = iap_calculate_firmware_crc32();

  if (calc_crc32 != exp_crc32 || !s_has_cached_chunk0)
  {
    LOG_ERR("Final CRC32 error! calc=0x%08X, exp=0x%08X", (unsigned int)calc_crc32, (unsigned int)exp_crc32);
    bsp_flash_erase_first_app_sector();
    bsp_flash_erase_anchor_sector();
    s_has_cached_chunk0 = false;
    ack_status = IAP_FINISH_STATUS_CRC_ERR;
    s_iap_state = IAP_STATE_ERROR;
    iap_send_frame(ACK_TH_FINISH, &ack_status, 1U);
    return;
  }

  /* 终验成功：先固化 Sector 127 锚点，再原子提交 Chunk 0 向量表 */
  flash_result_t anchor_res = iap_commit_anchor_metadata(exp_crc32);
  flash_result_t c0_res = bsp_flash_write_and_verify(APP_START_ADDR, s_chunk0_buf, CHUNK_MAX_SIZE);
  if (anchor_res != FLASH_STATUS_OK || c0_res != FLASH_STATUS_OK)
  {
    bsp_flash_erase_first_app_sector();
    bsp_flash_erase_anchor_sector();
    s_has_cached_chunk0 = false;
    ack_status = IAP_FINISH_STATUS_CRC_ERR;
    s_iap_state = IAP_STATE_ERROR;
    iap_send_frame(ACK_TH_FINISH, &ack_status, 1U);
    return;
  }

  LOG_INFO("Final CRC32 verified, Anchor & Chunk 0 committed! Jumping...");
  s_iap_state = IAP_STATE_FINISHED;
  iap_send_frame(ACK_TH_FINISH, &ack_status, 1U);
  for (volatile uint32_t delay = 0U; delay < 200000U; delay++) {}
  app_load(APP_START_ADDR);
}

/**
  * @brief  协议分发中心
  */
static void iap_dispatch_cmd(uint8_t cmd, const uint8_t *p_payload, uint16_t len)
{
  switch (cmd)
  {
    case CMD_TH_START_UPG:
      iap_handle_start_upg(p_payload, len);
      break;
    case CMD_TH_PUSH_CHUNK:
      iap_handle_push_chunk(p_payload, len);
      break;
    case CMD_TH_FINISH:
      iap_handle_finish(p_payload, len);
      break;
    default:
      break;
  }
}

/**
  * @brief  驱动处理串口升级接收状态机上下文
  */
typedef struct
{
  uint8_t  step;
  uint8_t  cmd;
  uint16_t len;
  uint16_t idx;
  uint8_t  payload[FRAME_MAX_PAYLOAD];
} iap_rx_ctx_t;

static iap_rx_ctx_t s_rx_ctx;

/**
  * @brief  驱动处理串口升级接收状态机
  */
void iap_upgrade_app_handle(void)
{
  uint8_t byte;
  while (bsp_uart1_read_byte(&byte))
  {
    if (s_rx_ctx.step == 0U && byte == FRAME_SOF1) { s_rx_ctx.step = 1U; }
    else if (s_rx_ctx.step == 1U) { s_rx_ctx.step = (byte == FRAME_SOF2) ? 2U : ((byte == FRAME_SOF1) ? 1U : 0U); }
    else if (s_rx_ctx.step == 2U) { s_rx_ctx.cmd = byte; s_rx_ctx.step = 3U; }
    else if (s_rx_ctx.step == 3U) { s_rx_ctx.len = (uint16_t)byte; s_rx_ctx.step = 4U; }
    else if (s_rx_ctx.step == 4U)
    {
      s_rx_ctx.len |= ((uint16_t)byte << 8U);
      s_rx_ctx.idx = 0U;
      s_rx_ctx.step = (s_rx_ctx.len > FRAME_MAX_PAYLOAD) ? 0U : ((s_rx_ctx.len == 0U) ? 6U : 5U);
    }
    else if (s_rx_ctx.step == 5U)
    {
      s_rx_ctx.payload[s_rx_ctx.idx++] = byte;
      if (s_rx_ctx.idx >= s_rx_ctx.len) { s_rx_ctx.step = 6U; }
    }
    else if (s_rx_ctx.step == 6U)
    {
      s_rx_ctx.step = 0U;
      uint8_t calc_cs = iap_checksum_calc(s_rx_ctx.cmd, s_rx_ctx.len, s_rx_ctx.payload);
      if (calc_cs == byte)
      {
        iap_dispatch_cmd(s_rx_ctx.cmd, s_rx_ctx.payload, s_rx_ctx.len);
      }
      else
      {
        LOG_ERR("Frame Checksum err: calc=0x%02X, rx=0x%02X", calc_cs, byte);
      }
    }
  }
}

