/**
  * @brief  在根目录下匹配升级固件 (方案 B: firmware.bin / firmwaremc.bin)
  */
static uint8_t find_upgrade_bin(const char *path)
{
  FRESULT res;
  FILINFO fno;
  DIR dir;

  res = f_opendir(&dir, path);
  if (res != FR_OK)
  {
    return 0;
  }

  s_bin_found = 0;
  while (f_readdir(&dir, &fno) == FR_OK && fno.fname[0] != 0)
  {
    if (fno.fname[0] == '.')
    {
      continue;
    }
    if (strcasecmp(fno.fname, UPGRADE_BIN_NAME) == 0)
    {
      s_upgrade_bin.base_addr = FLASH_APP_ADDR;
      s_upgrade_bin.filesize = fno.fsize;
      strncpy(s_upgrade_bin.bin_name, fno.fname, sizeof(s_upgrade_bin.bin_name) - 1);
      s_upgrade_bin.bin_name[sizeof(s_upgrade_bin.bin_name) - 1] = '\0';
      s_bin_found = 1;
      break;
    }
  }

  f_closedir(&dir);
  return s_bin_found;
}

/**
  * @brief  计算 Flash 数据的硬件 CRC32
  */
static uint32_t calculate_flash_crc(uint32_t base_addr, uint32_t filesize)
{
  uint32_t words = (filesize + 3U) / 4U;
  const uint32_t *p_flash = (const uint32_t *)base_addr;
  uint32_t crc_val = 0;

  crm_periph_clock_enable(CRM_CRC_PERIPH_CLOCK, TRUE);
  crc_data_reset();

  for (uint32_t i = 0; i < words; i++)
  {
    crc_val = crc_one_word_calculate(p_flash[i]);
  }

  crc_data_reset();
  crm_periph_clock_enable(CRM_CRC_PERIPH_CLOCK, FALSE);
  return crc_val;
}

/**
  * @brief  计算文件的硬件 CRC32 (限制在有效净荷范围内)
  */
static uint32_t calculate_file_crc(FIL *pfile, uint32_t filesize)
{
  uint8_t buffer[FLASH_CHUNK_SIZE];
  UINT bytes_read = 0;
  uint32_t crc_val = 0;
  uint32_t remaining = filesize;

  f_lseek(pfile, 0);
  crm_periph_clock_enable(CRM_CRC_PERIPH_CLOCK, TRUE);
  crc_data_reset();

  while (remaining > 0)
  {
    UINT to_read = (remaining > FLASH_CHUNK_SIZE) ? FLASH_CHUNK_SIZE : (UINT)remaining;
    if (f_read(pfile, buffer, to_read, &bytes_read) != FR_OK || bytes_read == 0)
    {
      break;
    }
    remaining -= bytes_read;

    for (UINT i = bytes_read; i < FLASH_CHUNK_SIZE; i++)
    {
      buffer[i] = 0xFF;
    }
    UINT words = (bytes_read + 3U) / 4U;
    const uint32_t *p_words = (const uint32_t *)buffer;
    for (UINT i = 0; i < words; i++)
    {
      crc_val = crc_one_word_calculate(p_words[i]);
    }
  }

  crc_data_reset();
  crm_periph_clock_enable(CRM_CRC_PERIPH_CLOCK, FALSE);
  return crc_val;
}

/**
  * @brief  擦除 App 空间对应的 Flash 扇区 (2KB 步长)
  */
static int flash_erase_sectors(uint32_t base_addr, uint32_t filesize)
{
  uint32_t sector_count = (filesize + FLASH_SECTOR_SIZE - 1U) / FLASH_SECTOR_SIZE;

  printf("Erasing %lu sectors (2KB each) from 0x%08lX...\r\n", sector_count, base_addr);
  flash_unlock();

  for (uint32_t i = 0; i < sector_count; i++)
  {
    uint32_t erase_addr = base_addr + (i * FLASH_SECTOR_SIZE);
    flash_status_type status = flash_sector_erase(erase_addr);
    if (status != FLASH_OPERATE_DONE)
    {
      flash_lock();
      printf("Erase failed at 0x%08lX: %d\r\n", erase_addr, status);
      return -1;
    }

    }
  }

  flash_lock();
  return 0;
}

/**
  * @brief  流式写入固件镜像 (限制在有效净荷范围内)
  */
static int flash_write_image(FIL *pfile, uint32_t base_addr, uint32_t filesize)
{
  uint8_t buffer[FLASH_CHUNK_SIZE];
  UINT bytes_read = 0;
  uint32_t curr_addr = base_addr;
  uint32_t remaining = filesize;

  printf("Writing image to Flash (%lu B)...\r\n", filesize);
  f_lseek(pfile, 0);
  flash_unlock();

  while (remaining > 0)
  {
    UINT to_read = (remaining > FLASH_CHUNK_SIZE) ? FLASH_CHUNK_SIZE : (UINT)remaining;
    if (f_read(pfile, buffer, to_read, &bytes_read) != FR_OK || bytes_read == 0)
    {
      flash_lock();
      return -1;
    }
    remaining -= bytes_read;

    for (UINT i = bytes_read; i < FLASH_CHUNK_SIZE; i++)
    {
      buffer[i] = 0xFF;
    }
    UINT words = (bytes_read + 3U) / 4U;
    const uint32_t *p_words = (const uint32_t *)buffer;
    for (UINT i = 0; i < words; i++)
    {
      flash_status_type status = flash_word_program(curr_addr + (i * 4U), p_words[i]);
      if (status != FLASH_OPERATE_DONE)
      {
        flash_lock();
        printf("Program failed at 0x%08lX: %d\r\n", curr_addr + (i * 4U), status);
        return -1;
      }
    }
    curr_addr += FLASH_CHUNK_SIZE;
  }

  flash_lock();
  return 0;
}

/**
  * @brief  擦除前固件预验签门禁 (选项 A: 严格防混刷与魔数校验)
  */
static int verify_firmware_trailer(FIL *pfile, uint32_t filesize, uint32_t *p_payload_len)
{
  fw_trailer_t trailer;
  UINT bytes_read = 0;

  if (pfile == NULL || p_payload_len == NULL || filesize < TRAILER_SIZE_BYTES)
  {
    printf("[PRE-VERIFY] Reject: File too small (%lu B, min %u B)\r\n",
           filesize, TRAILER_SIZE_BYTES);
    return -1;
  }

  if (f_lseek(pfile, filesize - TRAILER_SIZE_BYTES) != FR_OK ||
      f_read(pfile, &trailer, sizeof(fw_trailer_t), &bytes_read) != FR_OK ||
      bytes_read != sizeof(fw_trailer_t))
  {
    printf("[PRE-VERIFY] Reject: Failed to read 128B trailer\r\n");
    return -1;
  }

  if (trailer.magic != TRAILER_MAGIC_ATSG)
  {
    printf("[PRE-VERIFY] Reject: Bad magic 0x%08lX (Missing ATSG signature)\r\n", trailer.magic);
    return -1;
  }

  if (trailer.board_id != BOARD_ID_MC_AT32F435)
  {
    if (trailer.board_id == BOARD_ID_TH_AT32F423)
    {
      printf("[PRE-VERIFY] REJECTED: Cross-flashing blocked! TH firmware (0x%08lX) on MC board!\r\n",
             trailer.board_id);
    }
    else
    {
      printf("[PRE-VERIFY] REJECTED: Unknown Board ID 0x%08lX (Target MC: 0x%08lX)\r\n",
             trailer.board_id, (unsigned long)BOARD_ID_MC_AT32F435);
    }
    return -2;
  }

  if (trailer.payload_len != (filesize - TRAILER_SIZE_BYTES))
  {
    printf("[PRE-VERIFY] Reject: Payload length mismatch (%lu != %lu)\r\n",
           trailer.payload_len, (filesize - TRAILER_SIZE_BYTES));
    return -3;
  }

  *p_payload_len = trailer.payload_len;
  printf("[PRE-VERIFY] PASS: MC Firmware verified. Payload: %lu B, Ver: 0x%08lX\r\n",
         trailer.payload_len, trailer.fw_version);
  return 0;
}

/**
  * @brief  擦除、写入并校验升级镜像 (擦除前预验签门禁保护)
  */
static int write_bin_to_flash(void)
{
  uint32_t base_addr = s_upgrade_bin.base_addr;
  uint32_t filesize = s_upgrade_bin.filesize;
  uint32_t payload_len = 0;

  if (f_open(&s_file, s_upgrade_bin.bin_name, FA_READ) != FR_OK)
  {
    printf("Failed to open %s\r\n", s_upgrade_bin.bin_name);
    return -1;
  }

  /* 擦除前预验签门禁: 严格校验 Magic, Board ID 与 Trailer */
  if (verify_firmware_trailer(&s_file, filesize, &payload_len) != 0)
  {
    f_close(&s_file);
    printf("[SECURITY GATE] Pre-verification FAILED. Flash erase ABORTED!\r\n");
    return -1;
  }

  if (base_addr < FLASH_APP_ADDR || (base_addr + payload_len) > FLASH_END_ADDR)
  {
    f_close(&s_file);
    printf("Invalid firmware memory range: 0x%08lX + 0x%08lX\r\n", base_addr, payload_len);
    return -1;
  }

  /* 仅擦除与写入有效净荷代码 (payload_len)，不污染 Flash 空间 */
  if (flash_erase_sectors(base_addr, payload_len) != 0 ||
      flash_write_image(&s_file, base_addr, payload_len) != 0)
  {
    f_close(&s_file);
    return -1;
  }

  uint32_t crc_flash = calculate_flash_crc(base_addr, payload_len);
  uint32_t crc_file = calculate_file_crc(&s_file, payload_len);
  f_close(&s_file);

  if (crc_flash != crc_file)
  {
    printf("CRC Check Mismatch! Flash: 0x%08lX, File: 0x%08lX\r\n", crc_flash, crc_file);
    return -1;
  }

  printf("CRC32 Check OK: 0x%08lX\r\n", crc_flash);
  return 0;
}

