uint8_t is_app_valid(uint32_t address) {
  uint32_t msp = *(volatile uint32_t *)address;
  uint32_t reset_handler = *(volatile uint32_t *)(address + 4U);

  /* 校验主栈指针是否落在 384KB 片内 SRAM 范围 (0x20001000 - 0x20060000) */
  if (msp < 0x20001000U || msp > 0x20060000U) {
    return 0;
  }

  /* 校验复位向量是否落在 896KB 片内 App Flash 范围且 Thumb 位为 1 */
  if (reset_handler < 0x08020000U || reset_handler > 0x08100000U ||
      (reset_handler & 0x01U) == 0U) {
    return 0;
  }

  return 1;
}

/**
  * @brief  强制拉低 USB D+/D- 执行 SE0 物理断开
  * @param  duration_ms: 拉低维持时间 (毫秒)
  * @note   必须在 __disable_irq() 之前调用以保证 SysTick 延时正常运作
  */
static void usb_bus_disconnect_se0(uint32_t duration_ms) {
  gpio_init_type gpio_init_struct;

  crm_periph_clock_enable(OTG_PIN_GPIO_CLOCK, TRUE);
  gpio_default_para_init(&gpio_init_struct);

  gpio_init_struct.gpio_drive_strength = GPIO_DRIVE_STRENGTH_STRONGER;
  gpio_init_struct.gpio_out_type = GPIO_OUTPUT_PUSH_PULL;
  gpio_init_struct.gpio_mode = GPIO_MODE_OUTPUT;
  gpio_init_struct.gpio_pull = GPIO_PULL_NONE;
  gpio_init_struct.gpio_pins = OTG_PIN_DP | OTG_PIN_DM;
  gpio_init(OTG_PIN_GPIO, &gpio_init_struct);

  gpio_bits_reset(OTG_PIN_GPIO, OTG_PIN_DP | OTG_PIN_DM);
  delay_ms(duration_ms);
}

void jump_to_app(uint32_t address) {
  uint32_t stkptr = *(volatile uint32_t *)address;
  uint32_t jumpaddr = *(volatile uint32_t *)(address + 4U);

  /* 0. 强制拉低 D+/D- 200ms 执行 SE0 断开，确保 U 盘内部 PHY 感知断开并在 App 中可重新枚举 */
  usb_bus_disconnect_se0(200U);

  /* 1. 关闭全局中断 */
  __disable_irq();

  /* 2. 等待调试串口发送彻底完成并复位外设 */
  uint32_t uart_timeout = 200000U;
  while (usart_flag_get(USART1, USART_TDC_FLAG) == RESET) {
    uart_timeout--;
    if (uart_timeout == 0U) {
      break;
    }
  }
  usart_enable(USART1, FALSE);
  crm_periph_reset(CRM_USART1_PERIPH_RESET, TRUE);
  crm_periph_reset(CRM_USART1_PERIPH_RESET, FALSE);

  /* 3. 复位并关闭 USB 控制器与外设时钟 */
  nvic_irq_disable(OTGFS1_IRQn);
  __NVIC_ClearPendingIRQ(OTGFS1_IRQn);
  crm_periph_clock_enable(CRM_OTGFS1_PERIPH_CLOCK, FALSE);
  crm_periph_reset(CRM_OTGFS1_PERIPH_RESET, TRUE);
  crm_periph_reset(CRM_OTGFS1_PERIPH_RESET, FALSE);

  /* 4. 停止并清除 SysTick 定时器 */
  SysTick->CTRL = 0;
  SysTick->LOAD = 0;
  SysTick->VAL = 0;

  /* 5. 清除 NVIC 所有挂起与使能中断 */
  for (uint32_t i = 0; i < 8; i++) {
    NVIC->ICER[i] = 0xFFFFFFFF;
    NVIC->ICPR[i] = 0xFFFFFFFF;
  }

  /* 6. 重定向 VTOR 向量表 */
  SCB->VTOR = address;

  /* 7. 原子切换 MSP 并直接分支跳转至 Reset_Handler (汇编原子执行，绝不经过 C 栈) */
  __asm volatile (
    "msr msp, %0\n"
    "bx  %1\n"
    :
    : "r" (stkptr), "r" (jumpaddr)
    : "memory"
  );
}

static void usb_gpio_config(void) {
  gpio_init_type gpio_init_struct;

  /* 步骤 1: 强制推挽拉低 D+/D- 200ms，迫使 U 盘 PHY 彻底感知断开并复位端点 */
  usb_bus_disconnect_se0(200U);

  /* 步骤 2: 恢复为 USB 复用功能 MUX10 */
  gpio_default_para_init(&gpio_init_struct);
  gpio_init_struct.gpio_mode = GPIO_MODE_MUX;
  gpio_init(OTG_PIN_GPIO, &gpio_init_struct);

  gpio_pin_mux_config(OTG_PIN_GPIO, OTG_PIN_DP_SOURCE, OTG_PIN_MUX);
  gpio_pin_mux_config(OTG_PIN_GPIO, OTG_PIN_DM_SOURCE, OTG_PIN_MUX);
}

static void handle_no_disk_timeout(uint32_t ticks) {
  if (is_app_valid(FLASH_APP_ADDR)) {
    printf("Probe timeout. Valid App found at 0x%08X.\r\n", FLASH_APP_ADDR);
    printf("Jumping to application...\r\n");
    jump_to_app(FLASH_APP_ADDR);
  } else {
    /* 未找到有效 App 且无 U 盘时，每隔 1000ms (1 秒) 周期输出提示 */
    if ((ticks % 1000U) == 0U) {
      printf("No valid App at 0x%08X. Waiting for U-disk...\r\n",
             FLASH_APP_ADDR);
    }
  }
}

static void eeprom_startup_probe(void) {
  uint8_t test_val = 0U;
  eeprom_status_t status;

  bsp_eeprom_init();
  status = bsp_eeprom_read_byte(0x00U, &test_val);

  if (status == EEPROM_OK) {
    printf("[EEPROM] I2C2 PB10/PB11 @ 100K (Addr: 0xA0) -> SUCCESS! Byte[0x00] = 0x%02X\r\n", test_val);
    bsp_eeprom_dump(0x00U, 256U);
  } else {
    printf("[EEPROM] I2C2 PB10/PB11 @ 100K (Addr: 0xA0) -> FAILED (Status: %d)\r\n", (int)status);
  }
}

int main(void) {
  uint32_t hick_timeout = 1000000U;

  nvic_priority_group_config(NVIC_PRIORITY_GROUP_4);
  system_clock_config();
  timebase_init();
  uart_print_init(115200);

  printf("\r\n========================================\r\n");
  printf("  AT32F435 U-Disk Bootloader (" __DATE__ " " __TIME__ " | Build #%lu)\r\n", (uint32_t)BOOTLOADER_BUILD_NUMBER);
  printf("  Flash: 1024KB | Bl: 128KB | App: 0x08020000\r\n");
  printf("========================================\r\n");

  eeprom_startup_probe();

  usb_gpio_config();
  crm_periph_clock_enable(OTG_CLOCK, TRUE);

  /* 配置 48MHz HICK 高速内部时钟为 USB 时钟源 (对齐 MC_APP 硬件时钟树) */
  crm_clock_source_enable(CRM_CLOCK_SOURCE_HICK, TRUE);
  while (crm_flag_get(CRM_HICK_STABLE_FLAG) != SET && --hick_timeout > 0) {
  }
  crm_usb_clock_source_select(CRM_USB_CLOCK_SOURCE_HICK);

  nvic_irq_enable(OTG_IRQ, 0, 0);

  usbh_init(&otg_core_struct, USB_FULL_SPEED_CORE_ID, USB_ID,
            &uhost_msc_class_handler, &usbh_user_handle);

  /* 引入 200ms 总线物理稳定等待期，消除 U 盘上电暂态抖动 (对齐 mcu-p3) */
  delay_ms(200);

  printf("Probing for U-disk (2.0s timeout window)...\r\n");

  uint32_t last_tick = get_systick_ms();
  uint32_t probe_ticks = 0;

  while (1) {
    usbh_loop_handler(&otg_core_struct.host);

    if (g_upgrade_in_progress) {
      continue;
    }

    uint32_t now = get_systick_ms();
    if (now != last_tick) {
      probe_ticks += (now - last_tick);
      last_tick = now;

      if (probe_ticks >= 2000U && !g_udisk_connected) {
        handle_no_disk_timeout(probe_ticks);
      }
    }
  }
}

#!/usr/bin/env python3
"""Independent reference validator for MiniMCProto v2.0 offline test vectors (V2-P01D).

Pure Python 3 standard library implementation. Does NOT import or invoke any
production C/C++ library or test probe binary.
"""

import argparse
import copy
import hashlib
import json
from pathlib import Path
import struct
import sys
from typing import Any, Dict, List, Optional, Tuple

EXPECTED_PROTOCOL_SHA256 = "9f8d4f9607cb3e76cc30b9ee2f971b23c3e0d936611188466a71f4aa15f3ce54"
EXPECTED_CONTRACTS = {
    "V2-P01A": "5fc11e865fde44d780db94487855a7d762092a38362e9be66491b66626ad5ade",
    "V2-P01B": "25345c74b20051266626a1684be7f68f49bb570382969364b39301b7496a05e4",
}

REQUIRED_FUNCTIONAL_GROUPS = (
    "crc",
    "encode",
    "decode_bounds",
    "decode",
    "stream_sync",
    "stream_header",
    "stream_payload",
    "timeout",
    "recovery",
)
AUXILIARY_GROUPS = ("stub",)
ALL_ALLOWED_GROUPS = AUXILIARY_GROUPS + REQUIRED_FUNCTIONAL_GROUPS

REQUIRED_GOLDEN_HEX = {
    "V01": "55AA01020501040000000000F91E",
    "V02_INBOUND": "55AA010305030400010004007856341266B0",
    "V02_OUTBOUND": "55AA01030503030401000400785634127330",
    "V03": "55AA01020531040002000B000100000003000000473238A0DA",
    "V04": "55AA01FF14120400000000003DC1",
}

SOF1 = 0x55
SOF2 = 0xAA
MAX_PAYLOAD = 1024
HEADER_SIZE = 12
CRC_SIZE = 2
MIN_FRAME_SIZE = HEADER_SIZE + CRC_SIZE
TIMEOUT_MS = 50


def calc_crc16_ccitt_false(data: bytes) -> int:
    """Bit-by-bit reference CRC-16/CCITT-FALSE (poly=0x1021, init=0xFFFF, refin=False, refout=False, xorout=0x0000)."""
    crc = 0xFFFF
    for byte in data:
        crc ^= (byte & 0xFF) << 8
        for _ in range(8):
            if crc & 0x8000:
                crc = ((crc << 1) ^ 0x1021) & 0xFFFF
            else:
                crc = (crc << 1) & 0xFFFF
    return crc & 0xFFFF


def parse_hex_u16(text: str) -> int:
    if not isinstance(text, str) or not text.startswith("0x") or len(text) != 6:
        raise ValueError(f"invalid hex u16 string: {text!r}")
    return int(text, 16)


def build_payload_from_pattern(pattern: Dict[str, Any]) -> bytes:
    prefix = bytes.fromhex(pattern.get("prefix_hex", ""))
    pad_len = int(pattern.get("zero_pad_bytes", 0))
    suffix = bytes.fromhex(pattern.get("suffix_hex", ""))
    return prefix + (b"\x00" * pad_len) + suffix


def build_frame_from_pattern(pattern: Dict[str, Any]) -> bytes:
    header = bytes.fromhex(pattern["header_hex"])
    prefix = bytes.fromhex(pattern.get("payload_prefix_hex", ""))
    pad_len = int(pattern.get("payload_zero_pad_bytes", 0))
    suffix = bytes.fromhex(pattern.get("payload_suffix_hex", ""))
    crc_le = bytes.fromhex(pattern["crc_le_hex"])
    return header + prefix + (b"\x00" * pad_len) + suffix + crc_le


def reference_decode_frame(raw: bytes) -> Tuple[str, Optional[str], Optional[Dict[str, Any]]]:
    """Two-stage reference frame decoder matching V2-P01A & V2-P01B contracts."""
    if len(raw) < MIN_FRAME_SIZE:
        return "error", "frame_too_short", None
    seq, payload_len = struct.unpack_from("<HH", raw, 8)
    if payload_len > MAX_PAYLOAD:
        return "error", "mtu_exceeded", None
    if len(raw) != HEADER_SIZE + payload_len + CRC_SIZE:
        return "error", "length_mismatch", None

    sof_1, sof_2, src_id, dst_id, flags, cmd_id, hop_limit, route_ctrl = struct.unpack_from(
        "<BBBBBBBB", raw, 0
    )
    if sof_1 != SOF1 or sof_2 != SOF2:
        return "error", "bad_sof", None
    if (flags & 0x0C) != 0x04:
        return "error", "bad_version", None
    if (flags & 0xE0) != 0x00:
        return "error", "bad_flags_reserved", None
    if (route_ctrl & 0x03) == 0x03 or (route_ctrl & 0xF8) != 0x00:
        return "error", "bad_route_ctrl", None

    calc_crc = calc_crc16_ccitt_false(raw[: HEADER_SIZE + payload_len])
    recv_crc = struct.unpack_from("<H", raw, HEADER_SIZE + payload_len)[0]
    if calc_crc != recv_crc:
        return "error", "crc_mismatch", None

    payload = raw[HEADER_SIZE : HEADER_SIZE + payload_len]
    header_dict = {
        "sof_1": sof_1,
        "sof_2": sof_2,
        "src_id": src_id,
        "dst_id": dst_id,
        "flags": flags,
        "cmd_id": cmd_id,
        "hop_limit": hop_limit,
        "route_ctrl": route_ctrl,
        "seq": seq,
        "payload_len": payload_len,
    }
    return (
        "ok",
        None,
        {
            "header": header_dict,
            "payload": payload,
            "crc16": calc_crc,
        },
    )


def reference_validate_command(header: Dict[str, Any], payload: bytes) -> Tuple[bool, str]:
    """Validate V2-P01B command-level contract (GET_VERSION, VERSION_REPORT, PING, PONG) and OQ-01."""
    cmd_id = header["cmd_id"]
    flags = header["flags"]
    length = header["payload_len"]

    if cmd_id == 0x12:  # CMD_EMERGENCY_STOP (OQ-01 conflict in V04 when length == 0)
        return False, "OQ-01_emergency_stop_conflict_or_out_of_scope"
    if cmd_id == 0x01:  # CMD_GET_VERSION
        if length != 0 or (flags & 0x03) != 0x01:
            return False, "invalid_get_version"
        return True, "CMD_GET_VERSION"
    if cmd_id == 0x02:  # CMD_VERSION_REPORT
        if length != 16 or (flags & 0x03) != 0x02:
            return False, "invalid_version_report"
        proto_major, proto_minor = payload[0], payload[1]
        if proto_major != 2 or proto_minor != 0:
            return False, "invalid_version_report_proto"
        return True, "CMD_VERSION_REPORT"
    if cmd_id == 0x03:  # CMD_PING
        if length != 4 or (flags & 0x03) != 0x01:
            return False, "invalid_ping"
        return True, "CMD_PING"
    if cmd_id == 0x04:  # CMD_PONG
        if length != 12 or (flags & 0x03) != 0x02:
            return False, "invalid_pong"
        reserved = struct.unpack_from("<H", payload, 10)[0]
        if reserved != 0:
            return False, "invalid_pong_reserved"
        return True, "CMD_PONG"
    return False, "unsupported_cmd_in_v2_p01b"


class ReferenceStreamFSM:
    """Reference stream FSM implementing §6 of MiniMCProto v2.0 Rev 2.0.3."""

    def __init__(self) -> None:
        self.state = "WAIT_SOF1"
        self.count = 0
        self.last_byte_rx_ms = 0
        self.header_raw = bytearray(10)
        self.payload_buf = bytearray(MAX_PAYLOAD)
        self.crc_lo = 0
        self.candidate_payload_len = 0
        self.err_mtu = 0
        self.stat_crc_errors = 0
        self.stat_timeout_resets = 0
        self.frames: List[Dict[str, Any]] = []

    def reset(self) -> None:
        self.state = "WAIT_SOF1"
        self.count = 0
        self.candidate_payload_len = 0

    def poll_timeout(self, now_ms: int) -> None:
        if self.state != "WAIT_SOF1":
            elapsed = (now_ms - self.last_byte_rx_ms) & 0xFFFFFFFF
            if elapsed > TIMEOUT_MS:
                self.reset()
                self.stat_timeout_resets += 1

    def feed_byte(self, byte: int, now_ms: int) -> None:
        byte &= 0xFF
        if self.state != "WAIT_SOF1":
            elapsed = (now_ms - self.last_byte_rx_ms) & 0xFFFFFFFF
            if elapsed > TIMEOUT_MS:
                self.reset()
                self.stat_timeout_resets += 1

        if self.state == "WAIT_SOF1":
            if byte == SOF1:
                self.count = 1
                self.state = "WAIT_SOF2"
            else:
                self.state = "WAIT_SOF1"
        elif self.state == "WAIT_SOF2":
            if byte == SOF2:
                self.count = 0
                self.header_raw = bytearray(10)
                self.state = "READ_HEADER"
            elif byte == SOF1:
                self.count = 1
                self.state = "WAIT_SOF2"
            else:
                self.reset()
        elif self.state == "READ_HEADER":
            if self.count < 9:
                self.header_raw[self.count] = byte
                self.count += 1
            else:
                self.header_raw[9] = byte
                cand_len = self.header_raw[8] | (byte << 8)
                self.candidate_payload_len = cand_len
                if cand_len > MAX_PAYLOAD:
                    self.err_mtu += 1
                    self.reset()
                elif cand_len == 0:
                    self.count = 0
                    self.state = "READ_CRC"
                else:
                    self.count = 0
                    self.state = "READ_PAYLOAD"
        elif self.state == "READ_PAYLOAD":
            self.payload_buf[self.count] = byte
            if self.count < self.candidate_payload_len - 1:
                self.count += 1
            else:
                self.count = 0
                self.state = "READ_CRC"
        elif self.state == "READ_CRC":
            if self.count == 0:
                self.crc_lo = byte
                self.count = 1
            else:
                raw_frame = (
                    bytes([SOF1, SOF2])
                    + bytes(self.header_raw)
                    + bytes(self.payload_buf[: self.candidate_payload_len])
                    + bytes([self.crc_lo, byte])
                )
                status, err_code, decoded = reference_decode_frame(raw_frame)
                if status == "ok" and decoded is not None:
                    hdr = decoded["header"]
                    self.frames.append(
                        {
                            "src_id": hdr["src_id"],
                            "dst_id": hdr["dst_id"],
                            "flags": hdr["flags"],
                            "cmd_id": hdr["cmd_id"],
                            "hop_limit": hdr["hop_limit"],
                            "route_ctrl": hdr["route_ctrl"],
                            "seq": hdr["seq"],
                            "payload_len": hdr["payload_len"],
                            "payload_hex": decoded["payload"].hex().upper(),
                            "crc16_hex": f"0x{decoded['crc16']:04X}",
                        }
                    )
                elif err_code == "crc_mismatch":
                    self.stat_crc_errors += 1
                self.reset()

        self.last_byte_rx_ms = now_ms & 0xFFFFFFFF


def validate_vectors_data(data: Dict[str, Any]) -> Tuple[List[str], Dict[str, Any]]:
    errors: List[str] = []
    if not isinstance(data, dict):
        return ["root JSON value must be an object"], {}

    if not data.get("schema_version") or not isinstance(data.get("schema_version"), str):
        errors.append("missing or invalid schema_version")

    if data.get("protocol_sha256") != EXPECTED_PROTOCOL_SHA256:
        errors.append(
            f"protocol_sha256 mismatch: got {data.get('protocol_sha256')!r}, expected {EXPECTED_PROTOCOL_SHA256!r}"
        )

    consumed = data.get("consumed_contracts") or {}
    for contract_id, expected_sha in EXPECTED_CONTRACTS.items():
        actual_sha = (consumed.get(contract_id) or {}).get("sha256")
        if actual_sha != expected_sha:
            errors.append(f"consumed_contracts[{contract_id}] sha256 mismatch: {actual_sha!r}")

    # Validate 5 golden frames
    golden_frames = data.get("golden_frames")
    if not isinstance(golden_frames, list) or len(golden_frames) != 5:
        errors.append("golden_frames must contain exactly 5 authoritative vectors")
    else:
        seen_golden = set()
        for gf in golden_frames:
            vid = gf.get("vector_id")
            seen_golden.add(vid)
            if vid not in REQUIRED_GOLDEN_HEX:
                errors.append(f"unknown golden vector_id: {vid!r}")
                continue
            raw_hex = gf.get("raw_hex", "")
            if raw_hex != REQUIRED_GOLDEN_HEX[vid]:
                errors.append(f"golden vector {vid} raw_hex altered from specification")
                continue
            raw_bytes = bytes.fromhex(raw_hex)
            if gf.get("total_bytes") != len(raw_bytes):
                errors.append(f"golden vector {vid} total_bytes mismatch")
            status, err_code, decoded = reference_decode_frame(raw_bytes)
            if status != "ok" or decoded is None:
                errors.append(f"golden vector {vid} failed frame decode: {err_code}")
                continue
            expected_crc = parse_hex_u16(gf.get("expected_crc16_hex", ""))
            if decoded["crc16"] != expected_crc:
                errors.append(
                    f"golden vector {vid} CRC mismatch: calculated 0x{decoded['crc16']:04X} != {gf.get('expected_crc16_hex')}"
                )
            le_crc_hex = raw_bytes[-2:].hex().upper()
            if gf.get("expected_crc16_le_hex") != le_crc_hex:
                errors.append(f"golden vector {vid} expected_crc16_le_hex mismatch")
            for k, v in (gf.get("header") or {}).items():
                if decoded["header"].get(k) != v:
                    errors.append(f"golden vector {vid} header.{k} mismatch: {v} != {decoded['header'].get(k)}")
            cmd_ok, _ = reference_validate_command(decoded["header"], decoded["payload"])
            if gf.get("command_valid") is not cmd_ok:
                errors.append(
                    f"golden vector {vid} command_valid mismatch: got {gf.get('command_valid')}, expected {cmd_ok}"
                )
            if vid == "V04":
                if gf.get("frame_valid") is not True or gf.get("command_valid") is not False:
                    errors.append("V04 must have frame_valid=True and command_valid=False (OQ-01)")
                if "OQ-01" not in str(gf.get("conflict_status", "")):
                    errors.append("V04 must document OQ-01 conflict_status")

        if seen_golden != set(REQUIRED_GOLDEN_HEX.keys()):
            errors.append(f"missing required golden vectors: {set(REQUIRED_GOLDEN_HEX.keys()) - seen_golden}")

    # Validate cases
    cases = data.get("cases")
    if not isinstance(cases, list) or not cases:
        errors.append("cases list must be non-empty")
        return errors, {}

    seen_case_ids = set()
    group_counts: Dict[str, int] = {g: 0 for g in ALL_ALLOWED_GROUPS}

    for idx, case in enumerate(cases):
        cid = case.get("case_id")
        if not cid or not isinstance(cid, str):
            errors.append(f"case[{idx}] has empty or non-string case_id")
            continue
        if cid in seen_case_ids:
            errors.append(f"duplicate case_id: {cid}")
        seen_case_ids.add(cid)

        group = case.get("group")
        if group not in ALL_ALLOWED_GROUPS:
            errors.append(f"{cid}: unknown group {group!r}")
            continue
        group_counts[group] += 1

        if "raw_hex" not in case or not isinstance(case["raw_hex"], str):
            errors.append(f"{cid}: missing raw_hex string")
            continue
        try:
            bytes.fromhex(case["raw_hex"])
        except ValueError as exc:
            errors.append(f"{cid}: invalid raw_hex: {exc}")
            continue

        expected = case.get("expected") or {}
        inp = case.get("input") or {}

        if group == "stub":
            if expected.get("status") != "not_implemented":
                errors.append(f"{cid}: stub case must expect status='not_implemented'")

        elif group == "crc":
            if case.get("polarity") == "positive":
                raw_bytes = bytes.fromhex(case["raw_hex"])
                crc = calc_crc16_ccitt_false(raw_bytes)
                exp_crc = parse_hex_u16(expected.get("crc16_hex", ""))
                if crc != exp_crc:
                    errors.append(f"{cid}: CRC mismatch: calc 0x{crc:04X} != {expected.get('crc16_hex')}")
                le_hex = struct.pack("<H", crc).hex().upper()
                if expected.get("crc16_le_hex") != le_hex:
                    errors.append(f"{cid}: crc16_le_hex mismatch: {expected.get('crc16_le_hex')} != {le_hex}")
            else:
                if not (inp.get("null_pointer") and int(inp.get("declared_length", 0)) > 0):
                    errors.append(f"{cid}: negative crc case must specify null_pointer with non-zero length")
                if expected.get("status") != "error":
                    errors.append(f"{cid}: negative crc case must expect status='error'")

        elif group == "encode":
            hdr = inp.get("header") or {}
            payload_len = int(hdr.get("payload_len", 0))
            out_cap = int(inp.get("out_capacity", 0))
            if case.get("polarity") == "positive":
                if "payload_pattern" in inp:
                    payload = build_payload_from_pattern(inp["payload_pattern"])
                else:
                    payload = bytes.fromhex(inp.get("payload_hex", ""))
                if len(payload) != payload_len or payload_len > MAX_PAYLOAD or out_cap < payload_len + MIN_FRAME_SIZE:
                    errors.append(f"{cid}: positive encode case has invalid bounds")
                    continue
                header_bytes = struct.pack(
                    "<BBBBBBBBHH",
                    SOF1,
                    SOF2,
                    int(hdr["src_id"]),
                    int(hdr["dst_id"]),
                    int(hdr["flags"]),
                    int(hdr["cmd_id"]),
                    int(hdr["hop_limit"]),
                    int(hdr["route_ctrl"]),
                    int(hdr["seq"]),
                    payload_len,
                )
                crc = calc_crc16_ccitt_false(header_bytes + payload)
                frame = header_bytes + payload + struct.pack("<H", crc)
                if expected.get("encoded_len") != len(frame):
                    errors.append(f"{cid}: encoded_len mismatch")
                if "raw_hex" in expected and expected["raw_hex"] != frame.hex().upper():
                    errors.append(f"{cid}: encoded raw_hex mismatch")
                if "crc16_hex" in expected and parse_hex_u16(expected["crc16_hex"]) != crc:
                    errors.append(f"{cid}: encoded crc16_hex mismatch")
            else:
                if expected.get("status") != "error":
                    errors.append(f"{cid}: negative encode case must expect status='error'")
                err_code = expected.get("error_code")
                if payload_len > MAX_PAYLOAD:
                    if err_code != "mtu_exceeded":
                        errors.append(f"{cid}: expected mtu_exceeded for payload_len={payload_len}")
                elif inp.get("null_payload_pointer") and payload_len > 0:
                    if err_code != "invalid_argument":
                        errors.append(f"{cid}: expected invalid_argument for null_payload_pointer")
                elif out_cap < payload_len + MIN_FRAME_SIZE:
                    if err_code != "buffer_too_small":
                        errors.append(f"{cid}: expected buffer_too_small for out_capacity={out_cap}")
                else:
                    errors.append(f"{cid}: negative encode case is actually valid")

        elif group in ("decode_bounds", "decode"):
            if "frame_pattern" in inp:
                raw_bytes = build_frame_from_pattern(inp["frame_pattern"])
            else:
                raw_bytes = bytes.fromhex(case["raw_hex"])
            status, err_code, decoded = reference_decode_frame(raw_bytes)
            if status != expected.get("status"):
                errors.append(f"{cid}: decode status mismatch: calc {status} != {expected.get('status')}")
                continue
            if status == "error":
                if err_code != expected.get("error_code"):
                    errors.append(f"{cid}: decode error_code mismatch: calc {err_code} != {expected.get('error_code')}")
            elif decoded is not None:
                exp_hdr = expected.get("header") or {}
                for k, v in exp_hdr.items():
                    if decoded["header"].get(k) != v:
                        errors.append(f"{cid}: decoded header.{k} mismatch: {decoded['header'].get(k)} != {v}")
                if "payload_hex" in expected and decoded["payload"].hex().upper() != expected["payload_hex"]:
                    errors.append(f"{cid}: decoded payload_hex mismatch")
                if "crc16_hex" in expected and parse_hex_u16(expected["crc16_hex"]) != decoded["crc16"]:
                    errors.append(f"{cid}: decoded crc16_hex mismatch")
                if cid == "DEC-005":
                    cmd_ok, _ = reference_validate_command(decoded["header"], decoded["payload"])
                    if expected.get("frame_valid") is not True or expected.get("command_valid") is not False or cmd_ok:
                        errors.append("DEC-005 (V04) must have frame_valid=True and command_valid=False")

        elif group in ("stream_sync", "stream_header", "stream_payload", "timeout", "recovery"):
            fsm = ReferenceStreamFSM()
            if inp.get("feed_mode") == "byte_by_byte":
                raw_bytes = bytes.fromhex(inp["hex"])
                now_ms = int(inp.get("start_ms", 0))
                step_ms = int(inp.get("step_ms", 1))
                for b in raw_bytes:
                    fsm.feed_byte(b, now_ms)
                    now_ms += step_ms
            elif "frame_pattern" in inp:
                raw_bytes = build_frame_from_pattern(inp["frame_pattern"])
                now_ms = int(inp.get("now_ms", 0))
                for b in raw_bytes:
                    fsm.feed_byte(b, now_ms)
            elif "chunks" in inp:
                for chunk in inp["chunks"]:
                    now_ms = int(chunk["now_ms"])
                    for b in bytes.fromhex(chunk["hex"]):
                        fsm.feed_byte(b, now_ms)
                if inp.get("reset_after_feed"):
                    fsm.reset()
            elif "polls" in inp:
                for poll_ms in inp["polls"]:
                    fsm.poll_timeout(int(poll_ms))
            else:
                errors.append(f"{cid}: stream case missing input specification")
                continue

            if expected.get("final_state") != fsm.state:
                errors.append(f"{cid}: final_state mismatch: calc {fsm.state} != {expected.get('final_state')}")
            if expected.get("dispatched_frames") != len(fsm.frames):
                errors.append(
                    f"{cid}: dispatched_frames mismatch: calc {len(fsm.frames)} != {expected.get('dispatched_frames')}"
                )
            if "header_bytes_collected" in expected and expected["header_bytes_collected"] != fsm.count:
                errors.append(f"{cid}: header_bytes_collected mismatch: calc {fsm.count}")
            if "candidate_payload_len" in expected and expected["candidate_payload_len"] != fsm.candidate_payload_len:
                errors.append(f"{cid}: candidate_payload_len mismatch: calc {fsm.candidate_payload_len}")
            if "err_mtu_delta" in expected and expected["err_mtu_delta"] != fsm.err_mtu:
                errors.append(f"{cid}: err_mtu_delta mismatch: calc {fsm.err_mtu}")
            if "stat_crc_errors_delta" in expected and expected["stat_crc_errors_delta"] != fsm.stat_crc_errors:
                errors.append(f"{cid}: stat_crc_errors_delta mismatch: calc {fsm.stat_crc_errors}")
            if "stat_timeout_resets_delta" in expected and expected["stat_timeout_resets_delta"] != fsm.stat_timeout_resets:
                errors.append(f"{cid}: stat_timeout_resets_delta mismatch: calc {fsm.stat_timeout_resets}")
            if "frames" in expected:
                exp_frames = expected["frames"]
                if len(exp_frames) != len(fsm.frames):
                    errors.append(f"{cid}: frames length mismatch")
                else:
                    for f_idx, (ef, af) in enumerate(zip(exp_frames, fsm.frames)):
                        for fk, fv in ef.items():
                            if af.get(fk) != fv:
                                errors.append(f"{cid}: frame[{f_idx}].{fk} mismatch: calc {af.get(fk)} != {fv}")

    for req_group in REQUIRED_FUNCTIONAL_GROUPS:
        if group_counts.get(req_group, 0) <= 0:
            errors.append(f"functional group {req_group!r} has 0 cases")
    for aux_group in AUXILIARY_GROUPS:
        if group_counts.get(aux_group, 0) <= 0:
            errors.append(f"auxiliary group {aux_group!r} has 0 cases")

    summary = {
        "schema_version": data.get("schema_version"),
        "protocol_sha256": data.get("protocol_sha256"),
        "golden_frame_count": len(golden_frames) if isinstance(golden_frames, list) else 0,
        "total_case_count": len(cases),
        "group_counts": group_counts,
        "errors": errors,
    }
    return errors, summary


def run_self_check(base_data: Dict[str, Any]) -> int:
    """Inject negative mutations in memory and verify each is deterministically rejected."""
    base_errors, _ = validate_vectors_data(base_data)
    if base_errors:
        print(json.dumps({"self_check": "failed_baseline", "errors": base_errors}, indent=2))
        return 1

    mutations = []

    def add_mutation(name: str, mutator) -> None:
        cloned = copy.deepcopy(base_data)
        mutator(cloned)
        mutations.append((name, cloned))

    add_mutation(
        "corrupt_golden_v01_crc",
        lambda d: d["golden_frames"][0].__setitem__("expected_crc16_hex", "0xFFFF"),
    )
    add_mutation(
        "corrupt_case_crc_001",
        lambda d: d["cases"][4]["expected"].__setitem__("crc16_hex", "0x0000"),
    )
    add_mutation(
        "duplicate_case_id",
        lambda d: d["cases"][1].__setitem__("case_id", d["cases"][0]["case_id"]),
    )
    add_mutation(
        "empty_functional_group_timeout",
        lambda d: d.__setitem__("cases", [c for c in d["cases"] if c.get("group") != "timeout"]),
    )
    add_mutation(
        "tamper_protocol_sha256",
        lambda d: d.__setitem__("protocol_sha256", "0" * 64),
    )
    add_mutation(
        "violate_v04_oq01_command_valid",
        lambda d: d["golden_frames"][4].__setitem__("command_valid", True),
    )
    add_mutation(
        "corrupt_decode_expected_seq",
        lambda d: next(c for c in d["cases"] if c["case_id"] == "DEC-002")["expected"]["header"].__setitem__(
            "seq", 999
        ),
    )
    add_mutation(
        "corrupt_stream_expected_dispatched_frames",
        lambda d: next(c for c in d["cases"] if c["case_id"] == "REC-004")["expected"].__setitem__(
            "dispatched_frames", 99
        ),
    )

    results = []
    for name, mutated_data in mutations:
        errs, _ = validate_vectors_data(mutated_data)
        if not errs:
            print(
                json.dumps(
                    {"self_check": "failed", "mutation_not_rejected": name},
                    indent=2,
                )
            )
            return 1
        results.append({"mutation": name, "rejected": True, "simulated_exit_code": 1, "triggered_error": errs[0]})

    print(
        json.dumps(
            {
                "mode": "self-check",
                "status": "passed",
                "mutations_tested": len(results),
                "results": results,
                "exit_code": 0,
            },
            indent=2,
            ensure_ascii=False,
        )
    )
    return 0


def main() -> int:
    parser = argparse.ArgumentParser(description="MiniMCProto v2.0 independent reference vector validator")
    parser.add_argument("--vectors", required=True, type=Path, help="Path to vectors.json")
    mode = parser.add_mutually_exclusive_group(required=True)
    mode.add_argument("--check", action="store_true", help="Validate vectors.json")
    mode.add_argument("--self-check", action="store_true", help="Run negative mutation self-checks")
    args = parser.parse_args()

    if not args.vectors.is_file():
        print(json.dumps({"error": f"vectors file not found: {args.vectors}", "exit_code": 2}), file=sys.stderr)
        return 2

    raw_bytes = args.vectors.read_bytes()
    vectors_sha256 = hashlib.sha256(raw_bytes).hexdigest()
    try:
        data = json.loads(raw_bytes.decode("utf-8"))
    except Exception as exc:
        print(json.dumps({"error": f"invalid JSON: {exc}", "exit_code": 1}), file=sys.stderr)
        return 1

    if args.self_check:
        return run_self_check(data)

    errors, summary = validate_vectors_data(data)
    summary["mode"] = "check"
    summary["vectors_path"] = str(args.vectors)
    summary["vectors_sha256"] = vectors_sha256
    summary["exit_code"] = 0 if not errors else 1
    print(json.dumps(summary, indent=2, ensure_ascii=False))
    return 0 if not errors else 1


if __name__ == "__main__":
    raise SystemExit(main())
#!/usr/bin/env python3
"""MiniMCProto v2.0 Independent Expected-Comparison Test Runner (V2-P03F).

Executes the CLI test probe (`minimc-probe` / `minimc_probe`) against the frozen
golden and case vectors in `test_harness/test_cases/minimcproto/vectors.json`,
comparing actual probe stdout and exit codes against expected outcomes.

Strict Architectural Rules (per V2-P02C & V2-P03F):
1. Pure Python 3 standard library only; zero third-party packages.
2. Unidirectional expectation authority: never updates or derives expectations
   from production probe output.
3. No Empty Test Pass: executing 0 test cases is strictly rejected (exit code 2).
4. Stub isolation:
   - `--case-set all` executes only the 9 functional groups (60 cases),
     excluding `stub`.
   - `--case-set stub` executes only the `stub` group (`STUB-001`..`STUB-004`),
     asserting `exit_code == 126` and `error_code: not_implemented`.
   - Functional groups strictly reject `exit_code == 126` or `not_implemented`
     as FAIL (never skipped or treated as PASS).
"""

import argparse
import copy
import json
import os
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
from typing import Any, Dict, List, Optional, Tuple


DEFAULT_VECTORS_PATH = "test_harness/test_cases/minimcproto/vectors.json"
DEFAULT_TIMEOUT_SEC = 5.0

EXPECTED_FUNCTIONAL_GROUPS = (
    "crc",
    "encode",
    "decode_bounds",
    "decode",
    "stream_sync",
    "stream_header",
    "stream_payload",
    "timeout",
    "recovery",
)
EXPECTED_AUXILIARY_GROUPS = ("stub",)

# Command payload length rules from V2-P01B (`v2-commands.md`) for command-layer
# metadata verification on decoded frames (e.g., DEC-005 / V04 OQ-01).
COMMAND_PAYLOAD_LENGTHS = {
    0x01: 0,   # CMD_GET_VERSION
    0x02: 16,  # CMD_VERSION_REPORT
    0x03: 4,   # CMD_PING
    0x04: 12,  # CMD_PONG
    0x12: 2,   # CMD_EMERGENCY_STOP (requires 2-byte reason_code; L=0 is OQ-01 conflict)
}


def reconstruct_payload_from_pattern(pat: Dict[str, Any]) -> str:
    """Reconstruct hex string from a payload_pattern dictionary."""
    prefix_hex = str(pat.get("prefix_hex", "")).upper()
    zero_pad_bytes = int(pat.get("zero_pad_bytes", 0))
    suffix_hex = str(pat.get("suffix_hex", "")).upper()
    return prefix_hex + ("00" * zero_pad_bytes) + suffix_hex


def reconstruct_frame_from_pattern(pat: Dict[str, Any]) -> Tuple[str, str]:
    """Reconstruct full frame hex and payload hex from a frame_pattern dictionary."""
    header_hex = str(pat.get("header_hex", "")).upper()
    payload_prefix_hex = str(pat.get("payload_prefix_hex", "")).upper()
    payload_zero_pad_bytes = int(pat.get("payload_zero_pad_bytes", 0))
    payload_suffix_hex = str(pat.get("payload_suffix_hex", "")).upper()
    crc_le_hex = str(pat.get("crc_le_hex", "")).upper()
    payload_hex = payload_prefix_hex + ("00" * payload_zero_pad_bytes) + payload_suffix_hex
    frame_hex = header_hex + payload_hex + crc_le_hex
    return frame_hex, payload_hex


def build_probe_command(probe_path: str, case: Dict[str, Any]) -> List[str]:
    """Map a single test case from vectors.json to minimc-probe CLI arguments."""
    op = case.get("operation", "")
    inp = case.get("input", {}) or {}
    raw_hex = str(case.get("raw_hex", ""))

    if op == "crc":
        if inp.get("null_pointer"):
            declared_len = int(inp.get("declared_length", 0))
            return [probe_path, "crc", "--null-ptr", "--len", str(declared_len)]
        return [probe_path, "crc", f"--hex={raw_hex}"]

    if op == "encode":
        hdr = inp.get("header", {})
        cmd = [
            probe_path,
            "encode",
            "--src", str(hdr["src_id"]),
            "--dst", str(hdr["dst_id"]),
            "--cmd", str(hdr["cmd_id"]),
            "--seq", str(hdr["seq"]),
            "--flags", str(hdr["flags"]),
            "--hop", str(hdr["hop_limit"]),
            "--route", str(hdr["route_ctrl"]),
        ]
        if inp.get("null_payload_pointer"):
            cmd.append("--null-payload")
        else:
            if "payload_pattern" in inp:
                payload_hex = reconstruct_payload_from_pattern(inp["payload_pattern"])
            else:
                payload_hex = str(inp.get("payload_hex", ""))
            cmd.append(f"--payload-hex={payload_hex}")

        if "payload_len" in hdr:
            cmd.extend(["--payload-len", str(hdr["payload_len"])])
        if "out_capacity" in inp:
            cmd.extend(["--buf-size", str(inp["out_capacity"])])
        return cmd

    if op == "decode":
        if "frame_pattern" in inp:
            frame_hex, _ = reconstruct_frame_from_pattern(inp["frame_pattern"])
        else:
            frame_hex = raw_hex
        return [probe_path, "decode", f"--hex={frame_hex}"]

    if op in ("feed", "reset"):
        if op == "reset" and not inp.get("chunks") and not raw_hex:
            return [probe_path, "reset"]

        if inp.get("feed_mode") == "byte_by_byte":
            stream_hex = str(inp.get("hex", raw_hex))
            start_ms = int(inp.get("start_ms", 0))
            step_ms = int(inp.get("step_ms", 1))
            cmd = [
                probe_path,
                "feed",
                f"--stream-hex={stream_hex}",
                "--start-ms", str(start_ms),
                "--step-ms", str(step_ms),
            ]
        elif "frame_pattern" in inp:
            frame_hex, _ = reconstruct_frame_from_pattern(inp["frame_pattern"])
            now_ms = int(inp.get("now_ms", 0))
            cmd = [
                probe_path,
                "feed",
                f"--stream-hex={frame_hex}",
                "--timestamps-ms", str(now_ms),
            ]
        elif "chunks" in inp:
            chunks = inp["chunks"]
            stream_hex = ",".join(str(c.get("hex", "")) for c in chunks)
            timestamps_ms = ",".join(str(c.get("now_ms", 0)) for c in chunks)
            cmd = [
                probe_path,
                "feed",
                f"--stream-hex={stream_hex}",
                "--timestamps-ms", timestamps_ms,
            ]
        else:
            cmd = [
                probe_path,
                "feed",
                f"--stream-hex={raw_hex}",
                "--timestamps-ms", "0",
            ]

        if op == "reset" or inp.get("reset_after_feed"):
            cmd.append("--reset-after")
        return cmd

    if op == "poll":
        polls = inp.get("polls", [0])
        now_ms_str = ",".join(str(int(p)) for p in polls)
        return [probe_path, "poll", "--now-ms", now_ms_str]

    raise ValueError(f"Unsupported operation '{op}' in case '{case.get('case_id')}'")


def parse_probe_stdout(stdout_text: str) -> Dict[str, Any]:
    """Parse structured key-value stdout from minimc-probe."""
    result: Dict[str, Any] = {
        "frames": [],
        "counters": {},
    }
    section: Optional[str] = None

    for raw_line in stdout_text.splitlines():
        if not raw_line.strip():
            continue
        indent = len(raw_line) - len(raw_line.lstrip(" "))
        line = raw_line.strip()

        if indent == 0:
            section = None
            if line == "frames:":
                section = "frames"
                continue
            if line == "frames: []":
                result["frames"] = []
                continue
            if line == "counters:":
                section = "counters"
                continue
            if ":" in line:
                k, v = line.split(":", 1)
                result[k.strip()] = v.strip()
        else:
            if section == "frames" and line.startswith("- "):
                item_str = line[2:].strip()
                frame_dict: Dict[str, Any] = {}
                for part in item_str.split(", "):
                    if ":" not in part:
                        continue
                    fk, fv = part.split(":", 1)
                    fk = fk.strip()
                    fv = fv.strip()
                    if fk == "payload_hex":
                        if fv.startswith('"') and fv.endswith('"') and len(fv) >= 2:
                            fv = fv[1:-1]
                        frame_dict[fk] = fv
                    elif fk == "crc16_hex":
                        frame_dict[fk] = fv
                    else:
                        try:
                            frame_dict[fk] = int(fv, 0)
                        except ValueError:
                            frame_dict[fk] = fv
                result["frames"].append(frame_dict)
            elif section == "counters" and ":" in line:
                ck, cv = line.split(":", 1)
                ck = ck.strip()
                cv = cv.strip()
                try:
                    result["counters"][ck] = int(cv, 0)
                except ValueError:
                    result["counters"][ck] = cv

    return result


def evaluate_command_layer_on_decoded(parsed: Dict[str, Any]) -> Tuple[bool, Optional[str]]:
    """Evaluate V2-P01B command-layer validity and OQ-01 conflict on decoded frame fields."""
    if parsed.get("frame_valid") != "true":
        return False, None
    try:
        cmd_id = int(str(parsed.get("cmd_id", "0")), 0)
        payload_len = int(str(parsed.get("payload_len", "-1")), 0)
    except ValueError:
        return False, None

    if cmd_id == 0x12 and payload_len == 0:
        return False, "OQ-01"

    expected_len = COMMAND_PAYLOAD_LENGTHS.get(cmd_id)
    if expected_len is None:
        return False, None
    return (payload_len == expected_len), None


def verify_case_result(
    case: Dict[str, Any],
    exit_code: int,
    stdout_text: str,
    stderr_text: str,
) -> Tuple[bool, List[str], Dict[str, Any]]:
    """Compare parsed probe output and exit code against case['expected']."""
    diffs: List[str] = []
    parsed = parse_probe_stdout(stdout_text)
    group = case.get("group", "")
    op = case.get("operation", "")
    expected = case.get("expected", {}) or {}
    inp = case.get("input", {}) or {}

    # 1. Stub group handling
    if group == "stub" or expected.get("status") == "not_implemented":
        if exit_code != 126:
            diffs.append(f"stub expected exit_code=126, got exit_code={exit_code}")
        if parsed.get("status") != "error":
            diffs.append(f"stub expected status='error', got status={parsed.get('status')!r}")
        if parsed.get("error_code") != "not_implemented":
            diffs.append(
                f"stub expected error_code='not_implemented', got error_code={parsed.get('error_code')!r}"
            )
        return (len(diffs) == 0), diffs, parsed

    # 2. Functional group protection against unimplemented stubs
    if exit_code == 126 or parsed.get("error_code") == "not_implemented":
        diffs.append(
            f"unimplemented backend rejected on functional group '{group}' "
            f"(exit_code={exit_code}, error_code={parsed.get('error_code')!r})"
        )
        return False, diffs, parsed

    if exit_code != 0:
        diffs.append(
            f"probe exited with non-zero exit_code={exit_code} "
            f"(stderr={stderr_text.strip()!r})"
        )
        return False, diffs, parsed

    # 3. Verify all fields in expected
    handled_keys = set()

    if "status" in expected:
        handled_keys.add("status")
        act_status = parsed.get("status")
        if act_status != expected["status"]:
            diffs.append(f"status: expected {expected['status']!r}, got {act_status!r}")

    if "error_code" in expected:
        handled_keys.add("error_code")
        act_err = parsed.get("error_code")
        if act_err != expected["error_code"]:
            diffs.append(f"error_code: expected {expected['error_code']!r}, got {act_err!r}")
        if op == "decode":
            act_fv = parsed.get("frame_valid")
            if act_fv != "false":
                diffs.append(f"decode error must set frame_valid='false', got {act_fv!r}")

    if "crc16_hex" in expected:
        handled_keys.add("crc16_hex")
        act_crc = parsed.get("crc16_hex")
        if act_crc != expected["crc16_hex"]:
            diffs.append(f"crc16_hex: expected {expected['crc16_hex']!r}, got {act_crc!r}")

    if "crc16_le_hex" in expected:
        handled_keys.add("crc16_le_hex")
        act_le = parsed.get("crc16_le_hex")
        if act_le is None and op == "encode":
            raw_out = str(parsed.get("raw_hex", ""))
            if len(raw_out) >= 4:
                act_le = raw_out[-4:]
        if act_le != expected["crc16_le_hex"]:
            diffs.append(f"crc16_le_hex: expected {expected['crc16_le_hex']!r}, got {act_le!r}")

    if "encoded_len" in expected:
        handled_keys.add("encoded_len")
        try:
            act_len = int(str(parsed.get("encoded_len", "-1")), 0)
        except ValueError:
            act_len = -1
        if act_len != int(expected["encoded_len"]):
            diffs.append(f"encoded_len: expected {expected['encoded_len']}, got {act_len}")

    if "raw_hex" in expected:
        handled_keys.add("raw_hex")
        act_raw = parsed.get("raw_hex")
        if act_raw != expected["raw_hex"]:
            diffs.append(f"raw_hex: expected {expected['raw_hex']!r}, got {act_raw!r}")
    elif op == "encode" and expected.get("status") == "ok" and "payload_pattern" in inp:
        # Also verify full encoded frame hex when payload_pattern is used (e.g. ENC-005)
        hdr = inp["header"]
        hdr_bytes = struct.pack(
            "<BBBBBBBBHH",
            0x55,
            0xAA,
            int(hdr["src_id"]),
            int(hdr["dst_id"]),
            int(hdr["flags"]),
            int(hdr["cmd_id"]),
            int(hdr["hop_limit"]),
            int(hdr["route_ctrl"]),
            int(hdr["seq"]),
            int(hdr["payload_len"]),
        )
        expected_full_hex = (
            hdr_bytes.hex().upper()
            + reconstruct_payload_from_pattern(inp["payload_pattern"])
            + str(expected.get("crc16_le_hex", "")).upper()
        )
        act_raw = parsed.get("raw_hex", "")
        if act_raw != expected_full_hex:
            diffs.append(
                f"raw_hex (pattern): expected length {len(expected_full_hex)} matching pattern, "
                f"got length {len(act_raw)}"
            )

    if "frame_valid" in expected:
        handled_keys.add("frame_valid")
        exp_fv_str = "true" if expected["frame_valid"] else "false"
        act_fv_str = parsed.get("frame_valid")
        if act_fv_str != exp_fv_str:
            diffs.append(f"frame_valid: expected {exp_fv_str!r}, got {act_fv_str!r}")

    if "header" in expected:
        handled_keys.add("header")
        exp_hdr = expected["header"]
        # Check SOF1/SOF2 on positive decode
        if parsed.get("sof_1") != "0x55" or parsed.get("sof_2") != "0xAA":
            diffs.append(
                f"sof: expected ('0x55', '0xAA'), got ({parsed.get('sof_1')!r}, {parsed.get('sof_2')!r})"
            )
        for hk, hv in exp_hdr.items():
            raw_val = parsed.get(hk)
            try:
                act_val = int(str(raw_val), 0)
            except (TypeError, ValueError):
                act_val = None
            if act_val != int(hv):
                diffs.append(f"header.{hk}: expected {hv}, got {raw_val!r}")

    if "payload_hex" in expected:
        handled_keys.add("payload_hex")
        act_pld = parsed.get("payload_hex")
        if act_pld != expected["payload_hex"]:
            diffs.append(f"payload_hex: expected {expected['payload_hex']!r}, got {act_pld!r}")
    elif op == "decode" and expected.get("status") == "ok" and "frame_pattern" in inp:
        _, exp_payload_hex = reconstruct_frame_from_pattern(inp["frame_pattern"])
        act_pld = parsed.get("payload_hex", "")
        if act_pld != exp_payload_hex:
            diffs.append(
                f"payload_hex (pattern): expected length {len(exp_payload_hex)}, got length {len(act_pld)}"
            )

    if "command_valid" in expected or "conflict_id" in expected:
        act_cmd_valid, act_conflict_id = evaluate_command_layer_on_decoded(parsed)
        if "command_valid" in expected:
            handled_keys.add("command_valid")
            if act_cmd_valid != bool(expected["command_valid"]):
                diffs.append(
                    f"command_valid: expected {expected['command_valid']}, got {act_cmd_valid}"
                )
        if "conflict_id" in expected:
            handled_keys.add("conflict_id")
            if act_conflict_id != expected["conflict_id"]:
                diffs.append(
                    f"conflict_id: expected {expected['conflict_id']!r}, got {act_conflict_id!r}"
                )

    if "final_state" in expected:
        handled_keys.add("final_state")
        act_state = parsed.get("final_state")
        if act_state != expected["final_state"]:
            diffs.append(f"final_state: expected {expected['final_state']!r}, got {act_state!r}")

    if "header_bytes_collected" in expected:
        handled_keys.add("header_bytes_collected")
        try:
            act_hbc = int(str(parsed.get("header_bytes_collected", "-1")), 0)
        except ValueError:
            act_hbc = -1
        if act_hbc != int(expected["header_bytes_collected"]):
            diffs.append(
                f"header_bytes_collected: expected {expected['header_bytes_collected']}, got {act_hbc}"
            )

    if "candidate_payload_len" in expected:
        handled_keys.add("candidate_payload_len")
        try:
            act_cpl = int(str(parsed.get("candidate_payload_len", "-1")), 0)
        except ValueError:
            act_cpl = -1
        if act_cpl != int(expected["candidate_payload_len"]):
            diffs.append(
                f"candidate_payload_len: expected {expected['candidate_payload_len']}, got {act_cpl}"
            )

    if "dispatched_frames" in expected:
        handled_keys.add("dispatched_frames")
        exp_df = int(expected["dispatched_frames"])
        if op in ("feed", "reset") and "dispatched_frames_count" in parsed:
            try:
                act_dfc = int(str(parsed.get("dispatched_frames_count", "-1")), 0)
            except ValueError:
                act_dfc = -1
            act_cnt_df = parsed.get("counters", {}).get("dispatched_frames", act_dfc)
            if act_dfc != exp_df or act_cnt_df != exp_df:
                diffs.append(
                    f"dispatched_frames: expected {exp_df}, got count={act_dfc}, counter={act_cnt_df}"
                )
        elif op == "poll":
            if exp_df != 0:
                diffs.append(f"poll dispatched_frames: expected 0, got {exp_df}")

    if "err_mtu_delta" in expected:
        handled_keys.add("err_mtu_delta")
        act_mtu = parsed.get("counters", {}).get("err_mtu")
        if act_mtu != int(expected["err_mtu_delta"]):
            diffs.append(f"err_mtu_delta: expected {expected['err_mtu_delta']}, got {act_mtu}")

    if "stat_crc_errors_delta" in expected:
        handled_keys.add("stat_crc_errors_delta")
        act_crc_err = parsed.get("counters", {}).get("err_crc")
        if act_crc_err != int(expected["stat_crc_errors_delta"]):
            diffs.append(
                f"stat_crc_errors_delta: expected {expected['stat_crc_errors_delta']}, got {act_crc_err}"
            )

    if "stat_timeout_resets_delta" in expected:
        handled_keys.add("stat_timeout_resets_delta")
        if op == "poll":
            try:
                act_tmo = int(str(parsed.get("err_timeout", "-1")), 0)
            except ValueError:
                act_tmo = -1
        else:
            act_tmo = parsed.get("counters", {}).get("err_timeout")
        if act_tmo != int(expected["stat_timeout_resets_delta"]):
            diffs.append(
                f"stat_timeout_resets_delta: expected {expected['stat_timeout_resets_delta']}, got {act_tmo}"
            )

    if "frames" in expected:
        handled_keys.add("frames")
        exp_frames = expected["frames"]
        act_frames = parsed.get("frames", [])
        if len(act_frames) != len(exp_frames):
            diffs.append(
                f"frames length: expected {len(exp_frames)}, got {len(act_frames)}"
            )
        else:
            for idx, (ef, af) in enumerate(zip(exp_frames, act_frames)):
                for fk, fv in ef.items():
                    if af.get(fk) != fv:
                        diffs.append(
                            f"frames[{idx}].{fk}: expected {fv!r}, got {af.get(fk)!r}"
                        )

    unhandled = set(expected.keys()) - handled_keys
    if unhandled:
        diffs.append(f"unhandled expected keys: {sorted(unhandled)}")

    return (len(diffs) == 0), diffs, parsed


def run_case_suite(
    vectors_data: Dict[str, Any],
    probe_path: str,
    case_set: str,
    timeout_sec: float = DEFAULT_TIMEOUT_SEC,
    verbose: bool = False,
) -> Tuple[int, Dict[str, Any]]:
    """Run the selected case set against probe_path and return (exit_code, report_dict)."""
    report: Dict[str, Any] = {
        "case_set": case_set,
        "probe_path": probe_path,
        "total_cases": 0,
        "passed_cases": 0,
        "failed_cases": 0,
        "failures": [],
        "results": [],
    }

    # 1. Validate probe executable
    if not probe_path:
        report["error"] = "Probe path is empty or not specified"
        return 2, report
    probe_file = Path(probe_path)
    if not probe_file.exists() or not probe_file.is_file():
        report["error"] = f"Probe binary does not exist or is not a file: {probe_path}"
        return 2, report
    if not os.access(str(probe_file), os.X_OK):
        report["error"] = f"Probe binary is not executable: {probe_path}"
        return 2, report

    # 2. Validate vectors structure and select cases
    functional_groups = list(vectors_data.get("functional_groups", EXPECTED_FUNCTIONAL_GROUPS))
    auxiliary_groups = list(vectors_data.get("auxiliary_groups", EXPECTED_AUXILIARY_GROUPS))
    all_cases = vectors_data.get("cases", [])
    if not isinstance(all_cases, list) or len(all_cases) == 0:
        report["error"] = "Vectors file contains no cases"
        return 2, report

    if case_set == "all":
        selected_cases = [c for c in all_cases if c.get("group") in functional_groups]
    elif case_set in functional_groups or case_set in auxiliary_groups:
        selected_cases = [c for c in all_cases if c.get("group") == case_set]
    else:
        report["error"] = (
            f"Unknown case-set '{case_set}'. Allowed: 'all', 'stub', or one of {functional_groups}"
        )
        return 2, report

    # No Empty Test Pass invariant
    if len(selected_cases) == 0:
        report["error"] = f"No Empty Test Pass violation: 0 cases matched case-set '{case_set}'"
        return 2, report

    report["total_cases"] = len(selected_cases)

    # 3. Execute each case
    for case in selected_cases:
        case_id = str(case.get("case_id", "UNKNOWN"))
        group = str(case.get("group", ""))
        op = str(case.get("operation", ""))
        try:
            cmd = build_probe_command(str(probe_file), case)
        except Exception as exc:
            report["failed_cases"] += 1
            fail_entry = {
                "case_id": case_id,
                "group": group,
                "operation": op,
                "diffs": [f"command build error: {exc}"],
            }
            report["failures"].append(fail_entry)
            report["results"].append({"case_id": case_id, "passed": False, **fail_entry})
            continue

        try:
            proc = subprocess.run(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True,
                timeout=timeout_sec,
                check=False,
            )
        except subprocess.TimeoutExpired:
            report["failed_cases"] += 1
            fail_entry = {
                "case_id": case_id,
                "group": group,
                "operation": op,
                "diffs": [f"subprocess timeout after {timeout_sec}s"],
            }
            report["failures"].append(fail_entry)
            report["results"].append({"case_id": case_id, "passed": False, **fail_entry})
            continue
        except OSError as exc:
            report["error"] = f"Failed to execute probe subprocess: {exc}"
            return 2, report

        passed, diffs, parsed = verify_case_result(
            case, proc.returncode, proc.stdout, proc.stderr
        )
        case_record = {
            "case_id": case_id,
            "group": group,
            "operation": op,
            "exit_code": proc.returncode,
            "passed": passed,
            "expected": case.get("expected", {}),
            "actual_status": parsed.get("status"),
            "actual_error_code": parsed.get("error_code"),
            "diffs": diffs,
        }
        if verbose:
            case_record["stdout"] = proc.stdout.strip()
        report["results"].append(case_record)

        if passed:
            report["passed_cases"] += 1
        else:
            report["failed_cases"] += 1
            report["failures"].append(case_record)

    exit_code = 0 if report["failed_cases"] == 0 else 1
    return exit_code, report


def run_self_check(vectors_path: str) -> int:
    """Verify runner's own negative/exception defense paths without touching disk vectors."""
    base_vectors: Dict[str, Any] = {
        "functional_groups": list(EXPECTED_FUNCTIONAL_GROUPS),
        "auxiliary_groups": list(EXPECTED_AUXILIARY_GROUPS),
        "cases": [
            {
                "case_id": "CRC-001",
                "group": "crc",
                "operation": "crc",
                "polarity": "positive",
                "raw_hex": "313233343536373839",
                "expected": {
                    "status": "ok",
                    "crc16_hex": "0x29B1",
                    "crc16_le_hex": "B129",
                },
            },
            {
                "case_id": "STUB-001",
                "group": "stub",
                "operation": "crc",
                "polarity": "negative",
                "raw_hex": "313233343536373839",
                "expected": {
                    "status": "not_implemented",
                },
            },
        ],
    }
    if Path(vectors_path).is_file():
        try:
            with open(vectors_path, "r", encoding="utf-8") as f:
                base_vectors = json.load(f)
        except Exception:
            pass

    checks: List[Dict[str, Any]] = []

    with tempfile.TemporaryDirectory(prefix="minimc_runner_selfcheck_") as tmpdir:
        tmp_path = Path(tmpdir)

        # 1. Missing probe binary must be rejected with exit code 2
        missing_probe = str(tmp_path / "does_not_exist_probe")
        rc1, rep1 = run_case_suite(base_vectors, missing_probe, "crc")
        checks.append({
            "check_id": "SELF-01",
            "name": "missing_probe_rejected",
            "expected_exit_code": 2,
            "actual_exit_code": rc1,
            "passed": (rc1 == 2 and "does not exist" in rep1.get("error", "")),
            "detail": rep1.get("error", ""),
        })

        # 2. Non-executable probe file must be rejected with exit code 2
        non_exec_probe = tmp_path / "non_exec_probe"
        non_exec_probe.write_text("#!/bin/sh\necho ok\n", encoding="utf-8")
        os.chmod(non_exec_probe, 0o644)
        rc2, rep2 = run_case_suite(base_vectors, str(non_exec_probe), "crc")
        checks.append({
            "check_id": "SELF-02",
            "name": "non_executable_probe_rejected",
            "expected_exit_code": 2,
            "actual_exit_code": rc2,
            "passed": (rc2 == 2 and "not executable" in rep2.get("error", "")),
            "detail": rep2.get("error", ""),
        })

        # Create a dummy executable probe for group/timeout/mismatch checks
        ok_probe = tmp_path / "dummy_ok_probe.py"
        ok_probe.write_text(
            "#!/usr/bin/env python3\n"
            "print('status: ok\\ncrc16_hex: 0x29B1\\ncrc16_le_hex: B129')\n",
            encoding="utf-8",
        )
        os.chmod(ok_probe, 0o755)

        # 3. Unknown case-set name must be rejected with exit code 2
        rc3, rep3 = run_case_suite(base_vectors, str(ok_probe), "nonexistent_group")
        checks.append({
            "check_id": "SELF-03",
            "name": "unknown_case_set_rejected",
            "expected_exit_code": 2,
            "actual_exit_code": rc3,
            "passed": (rc3 == 2 and "Unknown case-set" in rep3.get("error", "")),
            "detail": rep3.get("error", ""),
        })

        # 4. Empty case-set (0 matching cases) must be rejected with exit code 2 (No Empty Test Pass)
        empty_crc_vectors = copy.deepcopy(base_vectors)
        empty_crc_vectors["cases"] = [
            c for c in empty_crc_vectors["cases"] if c.get("group") != "crc"
        ]
        rc4, rep4 = run_case_suite(empty_crc_vectors, str(ok_probe), "crc")
        checks.append({
            "check_id": "SELF-04",
            "name": "empty_case_set_rejected",
            "expected_exit_code": 2,
            "actual_exit_code": rc4,
            "passed": (rc4 == 2 and "No Empty Test Pass" in rep4.get("error", "")),
            "detail": rep4.get("error", ""),
        })

        # 5. Subprocess timeout must be caught and rejected with exit code 1
        sleep_probe = tmp_path / "dummy_sleep_probe.py"
        sleep_probe.write_text(
            "#!/usr/bin/env python3\nimport time\ntime.sleep(2.0)\n",
            encoding="utf-8",
        )
        os.chmod(sleep_probe, 0o755)
        crc_cases = [c for c in base_vectors["cases"] if c.get("group") == "crc"]
        single_crc_vectors = copy.deepcopy(base_vectors)
        single_crc_vectors["cases"] = crc_cases[:1]
        rc5, rep5 = run_case_suite(
            single_crc_vectors, str(sleep_probe), "crc", timeout_sec=0.1
        )
        timeout_diffs = (
            rep5["failures"][0]["diffs"] if rep5.get("failures") else []
        )
        checks.append({
            "check_id": "SELF-05",
            "name": "subprocess_timeout_rejected",
            "expected_exit_code": 1,
            "actual_exit_code": rc5,
            "passed": (
                rc5 == 1
                and any("timeout" in d for d in timeout_diffs)
            ),
            "detail": "; ".join(timeout_diffs),
        })

        # 6. Stub not_implemented (exit 126) on a functional group must be rejected with exit code 1
        stub_probe = tmp_path / "dummy_stub_probe.py"
        stub_probe.write_text(
            "#!/usr/bin/env python3\nimport sys\n"
            "print('status: error\\nerror_code: not_implemented')\n"
            "sys.exit(126)\n",
            encoding="utf-8",
        )
        os.chmod(stub_probe, 0o755)
        rc6, rep6 = run_case_suite(base_vectors, str(stub_probe), "crc")
        unimpl_diffs = (
            rep6["failures"][0]["diffs"] if rep6.get("failures") else []
        )
        checks.append({
            "check_id": "SELF-06",
            "name": "unimplemented_on_functional_group_rejected",
            "expected_exit_code": 1,
            "actual_exit_code": rc6,
            "passed": (
                rc6 == 1
                and any("unimplemented backend rejected" in d for d in unimpl_diffs)
            ),
            "detail": "; ".join(unimpl_diffs),
        })

        # 7. Output value mismatch must be rejected with exit code 1
        wrong_probe = tmp_path / "dummy_wrong_probe.py"
        wrong_probe.write_text(
            "#!/usr/bin/env python3\n"
            "print('status: ok\\ncrc16_hex: 0x0000\\ncrc16_le_hex: 0000')\n",
            encoding="utf-8",
        )
        os.chmod(wrong_probe, 0o755)
        rc7, rep7 = run_case_suite(single_crc_vectors, str(wrong_probe), "crc")
        mismatch_diffs = (
            rep7["failures"][0]["diffs"] if rep7.get("failures") else []
        )
        checks.append({
            "check_id": "SELF-07",
            "name": "output_value_mismatch_rejected",
            "expected_exit_code": 1,
            "actual_exit_code": rc7,
            "passed": (
                rc7 == 1
                and any("crc16_hex" in d for d in mismatch_diffs)
            ),
            "detail": "; ".join(mismatch_diffs),
        })

    all_passed = all(c["passed"] for c in checks)
    summary = {
        "mode": "self-check",
        "tested_exception_paths_count": len(checks),
        "passed_count": sum(1 for c in checks if c["passed"]),
        "failed_count": sum(1 for c in checks if not c["passed"]),
        "checks": checks,
        "status": "ok" if all_passed else "error",
        "exit_code": 0 if all_passed else 1,
    }
    print(json.dumps(summary, indent=2, ensure_ascii=False))
    return 0 if all_passed else 1


def main() -> int:
    parser = argparse.ArgumentParser(
        description="MiniMCProto v2.0 Independent Expected-Comparison Test Runner"
    )
    parser.add_argument(
        "--vectors",
        default=DEFAULT_VECTORS_PATH,
        help="Path to vectors.json (default: %(default)s)",
    )
    parser.add_argument(
        "--probe",
        default="",
        help="Path to compiled minimc-probe executable",
    )
    parser.add_argument(
        "--case-set",
        "--group",
        dest="case_set",
        default="all",
        help="Case group to run: 'all' (9 functional groups), 'stub', or a single group name",
    )
    parser.add_argument(
        "--timeout-sec",
        type=float,
        default=DEFAULT_TIMEOUT_SEC,
        help="Per-case subprocess timeout in seconds (default: %(default)s)",
    )
    parser.add_argument(
        "--verbose",
        action="store_true",
        help="Include raw probe stdout in per-case results",
    )
    parser.add_argument(
        "--self-check",
        action="store_true",
        help="Run runner self-check of negative/exception paths",
    )

    args = parser.parse_args()

    if args.self_check:
        return run_self_check(args.vectors)

    vectors_file = Path(args.vectors)
    if not vectors_file.exists() or not vectors_file.is_file():
        print(
            json.dumps(
                {
                    "status": "error",
                    "error": f"Vectors file does not exist: {args.vectors}",
                    "exit_code": 2,
                },
                indent=2,
                ensure_ascii=False,
            )
        )
        return 2

    try:
        with open(vectors_file, "r", encoding="utf-8") as f:
            vectors_data = json.load(f)
    except Exception as exc:
        print(
            json.dumps(
                {
                    "status": "error",
                    "error": f"Failed to parse vectors JSON: {exc}",
                    "exit_code": 2,
                },
                indent=2,
                ensure_ascii=False,
            )
        )
        return 2

    exit_code, report = run_case_suite(
        vectors_data=vectors_data,
        probe_path=args.probe,
        case_set=args.case_set,
        timeout_sec=args.timeout_sec,
        verbose=args.verbose,
    )
    report["status"] = "ok" if exit_code == 0 else "error"
    report["exit_code"] = exit_code
    print(json.dumps(report, indent=2, ensure_ascii=False))
    return exit_code


if __name__ == "__main__":
    sys.exit(main())
#!/usr/bin/env python3
"""MiniMCProto V2 跨仓（soc-ap / mcu-p3 MC / mcu-p3 TH）全量命令字静态对齐门禁。"""

import pathlib
import re
import sys
from typing import Dict, List, Set, Tuple

# 权威 MiniMCProto V2 命令字矩阵：(标准语义名, 期望数值, 允许别名元组)
EXPECTED_OPCODES: List[Tuple[str, int, Tuple[str, ...]]] = [
    ("ACK", 0x00, ("MINIMC_CMD_ACK",)),
    ("GET_VERSION", 0x01, ("MINIMC_CMD_GET_VERSION",)),
    ("VERSION_REPORT", 0x02, ("MINIMC_CMD_VERSION_REPORT",)),
    ("PING", 0x03, ("MINIMC_CMD_PING",)),
    ("PONG", 0x04, ("MINIMC_CMD_PONG",)),
    ("NACK", 0x06, ("MINIMC_CMD_NACK",)),
    ("SET_TEMP", 0x10, ("MINIMC_CMD_SET_TEMP",)),
    ("MOTION_HOME", 0x11, ("MINIMC_CMD_MOTION_HOME",)),
    ("MOTION_MOVE", 0x12, ("MINIMC_CMD_MOTION_MOVE",)),
    ("JOB_CONTROL", 0x13, ("MINIMC_CMD_JOB_CONTROL",)),
    ("TEMP_REPORT", 0x15, ("MINIMC_CMD_TEMP_REPORT", "MINIMC_CMD_TEMP_REPORT_V2")),
    ("POS_QUERY", 0x16, ("MINIMC_CMD_POS_QUERY",)),
    ("MOTION_STOP", 0x17, ("MINIMC_CMD_MOTION_STOP",)),
    ("LEVEL_GRID_QUERY", 0x18, ("MINIMC_CMD_LEVEL_GRID_QUERY",)),
    ("SLOT_SELECT", 0x19, ("MINIMC_CMD_SLOT_SELECT",)),
    ("LEVEL_TRIGGER", 0x1A, ("MINIMC_CMD_LEVEL_TRIGGER",)),
    ("GCODE_EXEC", 0x1C, ("MINIMC_CMD_GCODE_EXEC",)),
]

MACRO_RE = re.compile(
    r"(?:#define\s+|constexpr\s+uint8_t\s+)(MINIMC_CMD_[A-Z0-9_]+)\s*=?\s*(0x[0-9A-Fa-f]+)"
)


def parse_header_macros(paths: List[pathlib.Path]) -> Dict[str, int]:
    """从一组 C/C++ 头文件中提取 MINIMC_CMD_* 宏或常量定义映射表。"""
    if not paths:
        return {}
    macros: Dict[str, int] = {}
    for path in paths:
        if not path.is_file():
            raise FileNotFoundError(f"Missing required header file: {path}")
        content = path.read_text(encoding="utf-8")
        for match in MACRO_RE.finditer(content):
            macros[match.group(1)] = int(match.group(2), 16)
    return macros


def resolve_endpoint_opcode(
    macros: Dict[str, int],
    aliases: Tuple[str, ...],
) -> Tuple[int, List[str]]:
    """在单侧头文件宏字典中解析指定语义命令字的数值与不一致项。"""
    if not macros or not aliases:
        return -1, ["no macro found"]
    found_vals: Set[int] = set()
    for alias in aliases:
        if alias in macros:
            found_vals.add(macros[alias])
    if not found_vals:
        return -1, [f"missing any of {aliases}"]
    if len(found_vals) > 1:
        hex_list = [f"0x{v:02X}" for v in sorted(found_vals)]
        return -1, [f"conflicting alias values {hex_list} for {aliases}"]
    return next(iter(found_vals)), []


def verify_single_opcode(
    name: str,
    expected_val: int,
    aliases: Tuple[str, ...],
    endpoint_map: Dict[str, Dict[str, int]],
) -> List[str]:
    """校验单个命令字在 AP、MC、TH 三侧头文件中的定义是否与权威值严格一致。"""
    errors: List[str] = []
    for ep_label, macros in endpoint_map.items():
        actual_val, ep_errs = resolve_endpoint_opcode(macros, aliases)
        if ep_errs:
            errors.append(f"[{ep_label}] {name} (0x{expected_val:02X}): {'; '.join(ep_errs)}")
            continue
        if actual_val != expected_val:
            errors.append(
                f"[{ep_label}] {name} mismatch: expected 0x{expected_val:02X}, got 0x{actual_val:02X}"
            )
    return errors


def load_endpoint_headers(workspace_root: pathlib.Path) -> Dict[str, Dict[str, int]]:
    """加载 soc-ap、mcu-p3 (MC) 与 mcu-p3 (TH) 三侧协议头文件的命令字表。"""
    ap_headers = [
        workspace_root / "soc-ap/contracts/twin/telemetry_types.h",
    ]
    mc_headers = [
        workspace_root / "mcu-p3/motion-controller-mcu/project/inc/minimc_proto.h",
    ]
    th_headers = [
        workspace_root / "mcu-p3/color-engine-mcu/io_toggle/inc/minimc_proto.h",
    ]
    return {
        "soc-ap": parse_header_macros(ap_headers),
        "mcu-p3(MC)": parse_header_macros(mc_headers),
        "mcu-p3(TH)": parse_header_macros(th_headers),
    }


def main() -> int:
    """执行跨仓 MiniMCProto V2 命令字对齐检查，任何缺失或不一致返回非 0。"""
    workspace_root = pathlib.Path(__file__).resolve().parents[3]
    print("=== MiniMCProto V2 Cross-Repo Opcode Alignment Gate ===")
    try:
        endpoint_map = load_endpoint_headers(workspace_root)
    except FileNotFoundError as exc:
        print(f"[FATAL] {exc}", file=sys.stderr)
        return 1

    all_errors: List[str] = []
    for name, expected_val, aliases in EXPECTED_OPCODES:
        item_errs = verify_single_opcode(name, expected_val, aliases, endpoint_map)
        if item_errs:
            all_errors.extend(item_errs)
            print(f"  [FAIL] 0x{expected_val:02X} ({name})")
        else:
            print(f"  [OK]   0x{expected_val:02X} ({name:<17}) aligned across soc-ap / MC / TH")

    if all_errors:
        print("\n[FAILED] Opcode alignment check failed:", file=sys.stderr)
        for err in all_errors:
            print(f"  - {err}", file=sys.stderr)
        return 1

    print(f"\n[PASSED] All {len(EXPECTED_OPCODES)} MiniMCProto V2 opcodes are 100% aligned.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

