#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
scripts/verify_mcu_p3_uboot_suite.py
mcu-p3 固件基于 U-Disk Bootloader (uboot) 升级与兼容性多场景验证套件
支持场景: happy, cross, corrupt, repeat, nodisk, relay
"""

import argparse
import os
import re
import subprocess
import sys
import threading
import time
import serial

if hasattr(sys.stdout, 'reconfigure'):
    sys.stdout.reconfigure(encoding='utf-8', errors='replace')

PROBE_RS_EXE = "C:/Users/EDY/tools/probe-rs/probe-rs.exe"
MC_CHIP = "AT32F435VGT7"
MC_PROBE = "0483:3748:75003800120000334C41534E"
MC_PORT = "COM8"

TH_CHIP = "AT32F423CCT7"
TH_PROBE = "0483:3748:"
TH_PORT = "COM6"

BAUD = 115200


def parse_args():
    parser = argparse.ArgumentParser(description="mcu-p3 U-Disk Upgrade Test Suite")
    parser.add_argument(
        "--case",
        choices=["happy", "cross", "corrupt", "repeat", "nodisk", "relay", "monitor"],
        default="happy",
        help="Test case to execute and audit",
    )
    parser.add_argument("--duration", type=float, default=40.0, help="Log capture duration (s)")
    parser.add_argument("--no-reset", action="store_true", help="Do not trigger hardware reset via probe-rs")
    parser.add_argument("--log", type=str, default=None, help="Output audit log file path")
    return parser.parse_args()


def reset_mc():
    print(f"[RESET] Triggering MC ({MC_CHIP}) reset via probe-rs...")
    cmd = [PROBE_RS_EXE, "reset", "--chip", MC_CHIP, "--probe", MC_PROBE]
    try:
        with open(os.devnull, "r") as devnull:
            res = subprocess.run(cmd, stdin=devnull, capture_output=True, text=True, timeout=10)
        if res.returncode == 0:
            print("[RESET] MC reset OK.\n")
            return True
        else:
            print(f"[RESET] probe-rs warning (code {res.returncode}): {res.stderr}\n")
            return False
    except Exception as e:
        print(f"[RESET] probe-rs invocation failed: {e}\n")
        return False


def run_test_session(case_name, duration, do_reset, log_path):
    print("=" * 80)
    print(f" MCU-P3 UBOOT UPGRADE TEST: CASE [{case_name.upper()}]")
    print(f" Target Board: AT32F435 (MC) | Port: {MC_PORT} @ {BAUD}")
    if case_name == "relay":
        print(f" Relay Target: AT32F423 (TH) | Port: {TH_PORT} @ {BAUD}")
    print(f" Duration: {duration}s | Hardware Reset: {not do_reset}")
    print("=" * 80)

    mc_logs = []
    th_logs = []
    combined_logs = []
    running = True

    def log_line(source, text):
        now = time.strftime("%H:%M:%S")
        entry = f"[{now}] [{source}] {text}"
        combined_logs.append(entry)
        sys.stdout.write(entry + "\n")
        sys.stdout.flush()

    def read_port(port_name, tag, storage):
        try:
            ser = serial.Serial(port_name, BAUD, timeout=0.1)
            ser.reset_input_buffer()
            while running:
                line = ser.readline()
                if line:
                    decoded = line.decode("utf-8", errors="replace").rstrip("\r\n")
                    storage.append(decoded)
                    log_line(tag, decoded)
            ser.close()
        except Exception as e:
            log_line(f"{tag}_ERR", f"Port error: {e}")

    # 启动监听线程
    t_mc = threading.Thread(target=read_port, args=(MC_PORT, "MC", mc_logs), daemon=True)
    t_mc.start()

    t_th = None
    if case_name == "relay":
        t_th = threading.Thread(target=read_port, args=(TH_PORT, "TH", th_logs), daemon=True)
    report = format_audit_report(case_name, duration, combined_logs, audit_results)

    if log_path:
        os.makedirs(os.path.dirname(os.path.abspath(log_path)), exist_ok=True)
        with open(log_path, "w", encoding="utf-8") as f:
            f.write(report)
        print(f"\n[REPORT] Audit log successfully written to: {log_path}")

    all_pass = all(item[1] for item in audit_results)
    print("\n" + "=" * 80)
    print(f" CASE [{case_name.upper()}] FINAL VERDICT: {'ALL PASS' if all_pass else 'FAILED/INCOMPLETE'}")
    print("=" * 80)
    return all_pass


def evaluate_case(case, mc_lines, th_lines):
    results = []
    full_mc = "\n".join(mc_lines)
    full_th = "\n".join(th_lines)

    if case == "happy":
        # 1. 预验签通过
        has_preverify = bool(re.search(r"\[PRE-VERIFY\]\s*PASS:\s*MC Firmware verified", full_mc))
        results.append(("128B Trailer 擦除前预验签通过 (Board ID 0x43500001 匹配)", has_preverify))

