# CRC-16/CCITT-FALSE 独立纯算法参考实现
def calc_crc16(data: bytes) -> int:
    crc = 0xFFFF
    for byte in data:
        crc ^= (byte & 0xFF) << 8
        for _ in range(8):
            if crc & 0x8000:
                crc = ((crc << 1) ^ 0x1021) & 0xFFFF
            else:
                crc = (crc << 1) & 0xFFFF
    return crc & 0xFFFF


def verify_frame_hex(raw_hex: str) -> Tuple[bool, str]:
    """校验单帧十六进制字符串的物理完整性与 CRC"""
    try:
        raw = bytes.fromhex(raw_hex)
    except ValueError as e:
        return False, f"Hex decode error: {e}"

    if len(raw) < 14:
        return False, f"Frame too short: len={len(raw)} < 14"

    sof1, sof2 = raw[0], raw[1]
    if sof1 != 0x55 or sof2 != 0xAA:
        return False, f"Invalid SOF: {sof1:02X} {sof2:02X}"

    payload_len = raw[10] | (raw[11] << 8)
    expected_len = 12 + payload_len + 2
    if len(raw) != expected_len:
        return False, f"Length mismatch: raw={len(raw)}, expected={expected_len}"

    calc_c = calc_crc16(raw[: 12 + payload_len])
    recv_c = raw[12 + payload_len] | (raw[13 + payload_len] << 8)
    if calc_c != recv_c:
        return False, f"CRC mismatch: calc=0x{calc_c:04X}, recv=0x{recv_c:04X}"

    return True, "OK"


def validate_cases_manifest(data: Dict[str, Any]) -> List[str]:
    """全量校验黄金用例集格式、CRC 与字段映射"""
    errors = []
    pos_cases = data.get("positive_cases", [])
    neg_cases = data.get("negative_cases", [])

    if len(pos_cases) == 0:
        errors.append("Positive cases count is 0")
    if len(neg_cases) == 0:
        errors.append("Negative cases count is 0")

    # 校验所有正例中的帧
    for case in pos_cases:
        cid = case.get("case_id", "UNKNOWN")
        for key in ["req_frame_hex", "expected_response_hex", "req_frame_inbound_hex", 
                    "req_frame_outbound_relayed_hex", "resp_frame_th_native_hex"]:
            if key in case and case[key]:
                ok, msg = verify_frame_hex(case[key])
                if not ok:
                    errors.append(f"[{cid}] {key} invalid: {msg}")

    # 校验负例中注入的数据
    for case in neg_cases:
        cid = case.get("case_id", "UNKNOWN")
        inj = case.get("injected_traffic_hex", "")
        # 负例允许注入空数据、噪声或故意坏 CRC 的帧
        if inj and cid not in ["CAS-NEG-007", "CAS-NEG-009"]:
            ok, msg = verify_frame_hex(inj)
            if not ok:
                errors.append(f"[{cid}] injected_traffic_hex corrupted unexpectedly: {msg}")

    return errors


