/**
  **************************************************************************
  * @file     flash.c
  * @brief    Flash 2KB 扇区擦除、半字写入及即时物理回读驱动实现
  **************************************************************************
  */

#include "flash.h"
#include "iap.h"

/**
  * @brief  擦除指定的 2KB 物理扇区 (严格限制在 Bootloader 之外)
  * @param  sector_addr: 扇区起始物理地址
  * @retval 状态码
  */
flash_result_t bsp_flash_erase_sector(uint32_t sector_addr)
{
  /* 卫语句：校验扇区起始地址是否落在非 Bootloader 空间且按 2KB 对齐 */
  bool is_addr_in_range = (sector_addr >= APP_START_ADDR) &&
                          (sector_addr < (FLASH_BASE_ADDR + FLASH_TOTAL_SIZE));
  bool is_aligned = ((sector_addr % FLASH_SECTOR_SIZE) == 0U);
  if (!is_addr_in_range || !is_aligned)
  {
    return FLASH_STATUS_ERR_ADDR_RANGE;
  }

  /* 步骤 1: 解锁内部 Flash 控制器 */
  flash_unlock();

  /* 步骤 2: 执行扇区擦除 */
  flash_status_type status = flash_sector_erase(sector_addr);

  /* 步骤 3: 重新锁定内部 Flash */
  flash_lock();

  if (status != FLASH_OPERATE_DONE)
  {
    return FLASH_STATUS_ERR_ERASE;
  }

  return FLASH_STATUS_OK;
}

/**
  * @brief  擦除 Application 区域的首个扇区 (用于作废旧 App 向量)
  * @retval 状态码
  */
flash_result_t bsp_flash_erase_first_app_sector(void)
{
  return bsp_flash_erase_sector(APP_START_ADDR);
}

/**
  * @brief  擦除固件元数据锚点扇区 (Sector 127)
  * @retval 状态码
  */
flash_result_t bsp_flash_erase_anchor_sector(void)
{
  return bsp_flash_erase_sector(TRAILER_ANCHOR_ADDR);
}

/**
  * @brief  写入分块数据并执行即时物理回读比对
  * @param  write_addr: 写入物理地址
  * @param  p_buffer: 数据缓冲区指针
  * @param  len: 写入字节数
  * @retval 状态码
  */
flash_result_t bsp_flash_write_and_verify(uint32_t write_addr, const uint8_t *p_buffer, uint32_t len)
{
  /* 卫语句：非空与地址范围校验 */
  if (p_buffer == NULL || len == 0U)
  {
    return FLASH_STATUS_ERR_PARAM;
  }
  if ((write_addr < APP_START_ADDR) || ((write_addr + len) > (FLASH_BASE_ADDR + FLASH_TOTAL_SIZE)))
  {
    return FLASH_STATUS_ERR_ADDR_RANGE;
  }

  /* 步骤 1: 解锁 Flash 并流式写入半字 */
  flash_unlock();
  for (uint32_t i = 0U; i < len; i += 2U)
  {
    uint16_t low_byte = (uint16_t)p_buffer[i];
    uint16_t high_byte = (i + 1U < len) ? ((uint16_t)p_buffer[i + 1U] << 8U) : 0xFF00U;
    uint16_t half_word = low_byte | high_byte;

    flash_status_type prog_status = flash_halfword_program(write_addr + i, half_word);
    if (prog_status != FLASH_OPERATE_DONE)
    {
      flash_lock();
      return FLASH_STATUS_ERR_PROGRAM;
    }
  }
  flash_lock();

  /* 步骤 2: 逐字节执行硬件物理回读校验比对 */
  for (uint32_t j = 0U; j < len; j++)
  {
    uint8_t flash_val = *(volatile uint8_t *)(write_addr + j);
    if (flash_val != p_buffer[j])
    {
      return FLASH_STATUS_ERR_VERIFY;
    }
  }

  return FLASH_STATUS_OK;
}

/**
  * @brief  检查 Application 向量表与复位入口合法性
  * @retval true: 合法; false: 非法
  */
bool bsp_flash_app_vector_is_valid(void)
bool bsp_flash_app_vector_is_valid(void)
{
  /* 读取 App 栈顶指针与复位向量 */
  uint32_t app_msp = *(volatile uint32_t *)APP_START_ADDR;
  uint32_t app_entry = *(volatile uint32_t *)(APP_START_ADDR + 4U);

  /* 校验栈顶是否落在 48KB SRAM 范围 (0x20000000 ~ 0x2000C000) */
  bool is_msp_valid = (app_msp >= SRAM_START_ADDR) && (app_msp <= SRAM_END_ADDR);

  /* 校验复位入口是否落在 App Flash 范围且最高字节为 0x08 */
  bool is_entry_valid = (app_entry >= APP_START_ADDR) && (app_entry < APP_END_ADDR);

  return (is_msp_valid && is_entry_valid);
}

/**
  * @brief  穿透校验 Application 完整性 (第二道防线: 锚点 + 全片 CRC32)
  * @retval true: 完整健康; false: 损坏或位翻转
  */
bool bsp_flash_app_integrity_check(void)
{
  if (!bsp_flash_app_vector_is_valid())
  {
    return false;
  }

  const app_anchor_meta_t *p_anchor = (const app_anchor_meta_t *)TRAILER_ANCHOR_ADDR;
  if (p_anchor->anchor_magic == 0xFFFFFFFFUL)
  {
    LOG_INFO("No Anchor found in Sector 127 (raw ELF). Fallback to vector check.");
    return true;
  }
  if (p_anchor->anchor_magic != ANCHOR_MAGIC)
  {
    LOG_ERR("Anchor magic mismatch: 0x%08X", (unsigned int)p_anchor->anchor_magic);
    return false;
  }

  uint32_t calc_anchor_crc = iap_crc32_calc((const uint8_t *)p_anchor, 136U);
  if (calc_anchor_crc != p_anchor->anchor_crc32 || !iap_trailer_validate(&p_anchor->trailer))
  {
    LOG_ERR("Anchor CRC32 or trailer invalid!");
    return false;
  }

  uint32_t calc_fw_crc = iap_crc32_calc((const uint8_t *)APP_START_ADDR, p_anchor->trailer.payload_len);
  if (calc_fw_crc != p_anchor->firmware_crc32)
  {
    LOG_ERR("App CRC32 mismatch! exp=0x%08X, got=0x%08X",
            (unsigned int)p_anchor->firmware_crc32, (unsigned int)calc_fw_crc);
    return false;
  }

  LOG_INFO("App integrity 100%% verified via Sector 127 Anchor!");
  return true;
}

